import type { Quiz } from "./types";

export const aicpaAud2026Quiz: Quiz = {
  key: "aicpa-aud-2026",
  title: "2026 Official AICPA AUD Questions",
  subtitle: "Released AICPA AUD multiple-choice questions",
  discipline: "aud",
  course: "cpa",
  questions: [
    {
      id: "345070",
      prompt: `According to the AICPA Code of Professional Conduct, under which of the following circumstances may a CPA share confidential client information without the client's consent?`,
      choices: [
        `The CPA is approached by a financial advisor requesting the client's information to determine whether the client is a viable prospect.`,
        `The CPA is approached by a professional liability carrier requesting the client's information to determine whether the client is a viable prospect.`,
        `The CPA is approached by the client's outside counsel requesting the client's information to determine whether the CPA has performed any negligent acts against the client.`,
        `The CPA is approached by the CPA's professional liability company requesting the client's information in light of a potential lawsuit against the CPA.`,
      ],
      correctIndex: 3,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">D. The CPA's professional liability company requesting the client's information in light of a potential lawsuit against the CPA is correct.</strong> A CPA may release confidential client information when it is needed to defend the CPA against a claim.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">The <strong style="color:var(--mx-navy)">Confidential Client Information Rule</strong> bars a CPA in public practice from disclosing client information without the client's specific consent. The exceptions are short and closed: a valid <strong style="color:var(--mx-navy)">subpoena or summons</strong>, compliance with applicable law, an authorized <strong style="color:var(--mx-navy)">peer or quality review</strong>, an inquiry from an ethics division or trial board, and <strong style="color:var(--mx-navy)">self-defense</strong> against an actual or potential claim. Handing the file to the CPA's own insurer sits squarely in that last one.</p><p style="margin:0 0 18px">The contrast is what gets tested. These exceptions exist to protect the CPA's legal position or to satisfy a regulator, never to serve someone's <strong style="color:var(--mx-navy)">commercial interest</strong> and never to help an adversary build a case. If the requester wants the data to sell something, size up a business opportunity, or gather evidence against the CPA, consent or a subpoena is required no matter how ordinary the request sounds.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. Financial advisor screening the client as a prospect.</strong> This is a referral and marketing request, and CPAs trade names with advisors so often that it feels collegial rather than improper. But <strong style="color:var(--mx-navy)">prospecting is not an exception</strong>, and a benefit to the client does not substitute for permission. The CPA needs the client's consent before saying anything.<br /><br /><strong style="color:var(--mx-navy)">B. Professional liability carrier screening the client as a prospect.</strong> The phrase matches the correct answer almost word for word, which is the trap. Ask <strong style="color:var(--mx-navy)">whose insurer and for what purpose</strong>: here the carrier is shopping for a customer, not defending the CPA, and no claim exists. Selling insurance is a commercial purpose, so consent is required.<br /><br /><strong style="color:var(--mx-navy)">C. Client's outside counsel investigating the CPA's negligence.</strong> Students assume the client's own attorney stands in the client's shoes, so consent must be implied. It is not implied; the lawyer is an <strong style="color:var(--mx-navy)">adversary</strong> assembling a claim against the CPA, and voluntary disclosure to that party is unprotected. The CPA responds only to the client's consent or a valid subpoena.</p></div>`,},
    {
      id: "345071",
      prompt: `Prior to accepting an initial engagement to audit an issuer, an auditor is required to take each of the following actions with respect to previously performed tax services for the CFO, except`,
      choices: [
        `Discussing with the audit committee the potential effects of the relationship on auditor independence.`,
        `Advising the PCAOB in writing of the services rendered.`,
        `Documenting the substance of discussions the auditor has with the audit committee regarding the effects of the services rendered on independence.`,
        `Advising the audit committee in writing of the services rendered that may affect independence.`,
      ],
      correctIndex: 1,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">B. Advising the PCAOB in writing of the services rendered is correct.</strong> The pre-acceptance independence communication runs to the client's audit committee, not to the regulator.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Before accepting an <strong style="color:var(--mx-navy)">initial audit of an issuer</strong>, the firm must address any relationship that could bear on independence, including tax services previously provided to a person in a <strong style="color:var(--mx-navy)">financial reporting oversight role</strong> such as the CFO. Three actions are required, and all three point at the same audience: <strong style="color:var(--mx-navy)">describe the services in writing</strong> to the audit committee, <strong style="color:var(--mx-navy)">discuss</strong> with the committee how those services could affect independence, and <strong style="color:var(--mx-navy)">document the substance</strong> of that discussion.</p><p style="margin:0 0 18px">The trap is the recipient. The PCAOB writes the standards and inspects firms afterward, but it is not a mailbox for client-by-client independence notices at acceptance. The <strong style="color:var(--mx-navy)">audit committee is the gatekeeper</strong> that decides whether to hire the firm, so the writing, the conversation and the documentation all belong to it.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. Discussing with the audit committee the potential effects of the relationship on auditor independence.</strong> This is required, so it cannot be the exception. Students skip it because the written description feels sufficient on its own, but a <strong style="color:var(--mx-navy)">live discussion</strong> is mandated so the committee can weigh threats and safeguards before engaging the firm.<br /><br /><strong style="color:var(--mx-navy)">C. Documenting the substance of discussions the auditor has with the audit committee regarding the effects of the services rendered on independence.</strong> Also required. It tempts students because documentation feels like a fieldwork step rather than an <strong style="color:var(--mx-navy)">acceptance</strong> step, but the conversation must be evidenced in the acceptance workpapers; an undocumented discussion is treated as one that never occurred.<br /><br /><strong style="color:var(--mx-navy)">D. Advising the audit committee in writing of the services rendered that may affect independence.</strong> This is the core requirement the question is built around. It is easy to confuse with choice B because both say <strong style="color:var(--mx-navy)">in writing</strong>; the only difference is who receives it, and the written description goes to the audit committee.</p></div>`,},
    {
      id: "339050",
      prompt: `In an engagement under generally accepted government auditing standards, which of the following would impair an auditor's independence?`,
      choices: [
        `Providing benchmarking studies.`,
        `Carrying out internal audit functions.`,
        `Providing training to entity employees on limited technical issues.`,
        `Advising entity management on issues based on the auditor's knowledge.`,
      ],
      correctIndex: 1,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">B. Carrying out internal audit functions is correct.</strong> Running the client's internal audit function means taking on a job that belongs to management, and no safeguard cures that.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Government auditing standards require independence <strong style="color:var(--mx-navy)">in mind and in appearance</strong>, and every nonaudit service is measured against two bright lines: the auditor must not <strong style="color:var(--mx-navy)">assume management responsibilities</strong>, and the auditor must not <strong style="color:var(--mx-navy)">audit his own work</strong>. Operating the internal audit function fails both. Internal auditing is ongoing monitoring that the entity owns, and the auditor would later be evaluating controls he himself was running.</p><p style="margin:0 0 18px">Contrast that with services that only supply <strong style="color:var(--mx-navy)">information, data or explanation</strong>. Those are permitted when management designates someone with <strong style="color:var(--mx-navy)">suitable skills, knowledge and experience</strong> to oversee the work, accepts responsibility for the results, and makes every decision. The question to ask is whether the auditor is deciding and operating, or merely informing.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. Providing benchmarking studies.</strong> This is <strong style="color:var(--mx-navy)">advisory work</strong>: the auditor compiles comparative data and hands it over. Students are tempted because that data may drive budget or staffing choices, and they assume any input into a decision is a management responsibility. Management still evaluates the study and makes the call, so independence holds.<br /><br /><strong style="color:var(--mx-navy)">C. Providing training to entity employees on limited technical issues.</strong> Training is an <strong style="color:var(--mx-navy)">educational service</strong>, such as explaining how a new reporting requirement works. It looks risky because teaching the client feels like helping build the records the auditor will later examine. But routine training produces no records and no controls, it only builds staff competence, so there is nothing to self-review.<br /><br /><strong style="color:var(--mx-navy)">D. Advising entity management on issues based on the auditor's knowledge.</strong> This is <strong style="color:var(--mx-navy)">routine consultation</strong>, the ordinary exchange of technical advice and best practices. The confusion is treating advice as equivalent to decision making. Independence is impaired only when the auditor actually makes the decision or management cannot evaluate the recommendation; sharing knowledge while management stays responsible is allowed.</p></div>`,},
    {
      id: "33050",
      prompt: `Which of the following would most likely impede an auditor's professional skepticism during an audit of an issuer?`,
      choices: [
        `Workload demands of the engagement team.`,
        `The audit firm's strong system of quality control.`,
        `The auditor's responsibility to users of the audit report.`,
        `The firm's overriding duty to put the interest of investors first.`,
      ],
      correctIndex: 0,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">A. Workload demands of the engagement team is correct.</strong> Time pressure pushes auditors to accept weak evidence rather than chase it down.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Professional skepticism is a <strong style="color:var(--mx-navy)">questioning mind</strong> and a critical assessment of audit evidence. It is fragile, and what breaks it is usually <strong style="color:var(--mx-navy)">situational pressure</strong>: excessive workloads, unrealistic deadlines, fee and budget squeezes, and thin staffing. A rushed auditor takes management's explanation at face value instead of corroborating it, and stops following up on the inconsistencies that matter.</p><p style="margin:0 0 18px">The other classic impediments are <strong style="color:var(--mx-navy)">over-reliance on management's honesty</strong> from a long client relationship and <strong style="color:var(--mx-navy)">confirmation bias</strong>, looking only for evidence that supports the assertion. Everything else in this question points the other way: firm structures and public duties are designed to <strong style="color:var(--mx-navy)">reinforce</strong> skepticism, not erode it.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">B. The audit firm's strong system of quality control.</strong> Quality control is the firm's defense against exactly the pressure in choice A: staffing decisions, consultation requirements and an <strong style="color:var(--mx-navy)">engagement quality review</strong> that forces a second person to challenge risky conclusions. Students pick it because the question sits in a quality control topic and they expect the answer to name that system. A strong system is an enhancer; only a weak or ignored one creates risk.<br /><br /><strong style="color:var(--mx-navy)">C. The auditor's responsibility to users of the audit report.</strong> This duty is the <strong style="color:var(--mx-navy)">source</strong> of the obligation to stay skeptical, since strangers rely on the opinion without ever seeing the workpapers. The temptation comes from confusing responsibility to report users with pressure from the client to keep them happy, which is a real threat. Responsibility owed to third parties makes an auditor harder on the evidence, not softer.<br /><br /><strong style="color:var(--mx-navy)">D. The firm's overriding duty to put the interest of investors first.</strong> That is the <strong style="color:var(--mx-navy)">public watchdog role</strong>, and it is why the auditor works for investors rather than for management. The word overriding reads like a competing pressure or a bias, which is the trap. Putting investors first drives more rigorous testing of management's representations.</p></div>`,},
    {
      id: "343050",
      prompt: `Which of the following engagements requires a practitioner to comply with the provisions of Statements on Standards for Attestation Engagements (SSAE)?`,
      choices: [
      `Performing agreed-upon procedures by sending accounts receivable confirmations and reporting the findings.`,
      `Preparing financial statements for a client.`,
      `Performing bookkeeping and payroll services for a client.`,
      `Reviewing and reporting on an audit client's interim financial information.`,
    ],
      correctIndex: 0,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">A. Performing agreed-upon procedures by sending accounts receivable confirmations and reporting the findings is correct.</strong> The practitioner reports factual findings on someone else's subject matter, which is exactly what the attestation standards cover.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">The attestation standards cover engagements in which a practitioner issues a report on <strong style="color:var(--mx-navy)">subject matter, or an assertion about subject matter, that is the responsibility of another party</strong>. They come in three formats: examinations, reviews and <strong style="color:var(--mx-navy)">agreed-upon procedures</strong>. In an agreed-upon procedures engagement the practitioner performs the specific procedures the engaging party asks for, here confirming receivable balances, and reports the <strong style="color:var(--mx-navy)">factual findings</strong> without expressing an opinion or a conclusion.</p><p style="margin:0 0 18px">The other half of the rule is what the distractors test. SSAE is the <strong style="color:var(--mx-navy)">residual set of standards</strong>: it applies only when no other body of standards already claims the service. Audits and reviews of interim information for an audit client belong to the <strong style="color:var(--mx-navy)">auditing standards</strong>, or to PCAOB standards for an issuer. Preparation, compilation and review of historical financial statements for a nonissuer belong to <strong style="color:var(--mx-navy)">SSARS</strong>. Straight bookkeeping produces no report at all.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">B. Preparing financial statements for a client.</strong> Preparation is a <strong style="color:var(--mx-navy)">nonattest service performed under SSARS</strong>, with no report and no assurance. Students pick it because financial statements feel like the classic subject matter of a professional engagement. The practitioner here is helping build the statements, not reporting on another party's assertion.<br /><br /><strong style="color:var(--mx-navy)">C. Performing bookkeeping and payroll services for a client.</strong> These are pure <strong style="color:var(--mx-navy)">nonattest services</strong>, and the practitioner issues no report on anything. The temptation comes from remembering that such work raises independence and management-responsibility concerns under the ethics rules. Independence questions do not convert a service into an attestation engagement.<br /><br /><strong style="color:var(--mx-navy)">D. Reviewing and reporting on an audit client's interim financial information.</strong> This is the strongest distractor because it does produce a report and does give <strong style="color:var(--mx-navy)">limited assurance</strong>, so it looks like the attestation review format. But an interim review for an existing audit client is governed by the <strong style="color:var(--mx-navy)">auditing standards</strong> for a nonissuer and by PCAOB standards for an issuer. Assurance level never decides the standard; the type of engagement does.</p></div>`,},
    {
      id: "340050",
      prompt: `When an accountant discovers fraud while performing a review engagement, the accountant should do each of the following, except`,
      choices: [
        `Notify management at a higher level than the likely perpetrator of the fraud.`,
        `Consider consulting legal counsel.`,
        `Disclose the matter in the review report.`,
        `Consider resigning from the engagement.`,
      ],
      correctIndex: 2,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">C. Disclose the matter in the review report is correct.</strong> Fraud triggers communication inside the client and evaluation of the statements, not a narrative added to the accountant's report.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">When an accountant finds evidence of fraud during a review, the response is <strong style="color:var(--mx-navy)">communication, not publication</strong>. The matter goes to the appropriate level of management, <strong style="color:var(--mx-navy)">at least one level above anyone likely involved</strong>, and to those charged with governance when senior management may be implicated. The accountant then evaluates whether the fraud caused a <strong style="color:var(--mx-navy)">material misstatement</strong>.</p><p style="margin:0 0 18px">The review report is a narrow document. It gives <strong style="color:var(--mx-navy)">limited assurance</strong> and is modified only for a <strong style="color:var(--mx-navy)">departure from the applicable financial reporting framework</strong>. Fraud reaches the report indirectly at most: if it produced a material misstatement and management refuses to correct it, the accountant modifies the report for the departure or <strong style="color:var(--mx-navy)">withdraws</strong>. Simply describing the wrongdoing in the report is never the remedy, and disclosure outside the client normally requires <strong style="color:var(--mx-navy)">consent or a specific legal requirement</strong>.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. Notify management at a higher level than the likely perpetrator of the fraud.</strong> This is the first required step, and it exists so the investigation is not handed to the person who may have committed the fraud. Students hesitate because a review is only limited assurance, but the <strong style="color:var(--mx-navy)">communication duty does not depend on the level of assurance</strong>. Since the accountant should do this, it cannot be the exception.<br /><br /><strong style="color:var(--mx-navy)">B. Consider consulting legal counsel.</strong> Fraud raises questions about confidentiality, liability and any reporting obligation to outside parties, so counsel is an appropriate step. The word <strong style="color:var(--mx-navy)">consider</strong> is the giveaway: the option calls for judgment, not a mandated act, which makes it easy to accept. It is something the accountant should do, so it is not the answer.<br /><br /><strong style="color:var(--mx-navy)">D. Consider resigning from the engagement.</strong> Withdrawal is the proper response when management or those charged with governance lack integrity, refuse to act, or the fraud is pervasive enough that the work cannot be completed. Students sometimes read resignation as too extreme for a review, but <strong style="color:var(--mx-navy)">withdrawal is exactly the remedy</strong> when the client will not cooperate. The accountant should consider it, so it is not the exception.</p></div>`,},
    {
      id: "32050",
      prompt: `For an audit of a nonissuer, what information is least important to include in audit documentation?`,
      choices: [
        `The date on which audit work was completed.`,
        `The number of hours worked by the auditor on the audit area.`,
        `The name of the person who performed the audit work.`,
        `The name of the person who reviewed the audit work.`,
      ],
      correctIndex: 1,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">B. The number of hours worked by the auditor on the audit area is correct.</strong> Hours charged are a billing statistic, not evidence supporting the opinion.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Audit documentation exists to prove two things: that the auditor had a <strong style="color:var(--mx-navy)">sufficient basis for the report</strong>, and that the engagement was planned and performed in accordance with generally accepted auditing standards. The working test is whether an <strong style="color:var(--mx-navy)">experienced auditor with no prior connection</strong> to the engagement could read the file and understand the nature, timing and extent of the procedures, the results and evidence obtained, and the significant judgments reached.</p><p style="margin:0 0 18px">The standards also require <strong style="color:var(--mx-navy)">explicit ownership</strong> of the work: who performed each procedure and when it was completed, and who reviewed it and when that review occurred. Hours charged are a <strong style="color:var(--mx-navy)">practice management</strong> number. They drive billing, payroll and budget-to-actual analysis, but they add nothing to the evidence behind the opinion, so the audit file is complete without them.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. The date on which audit work was completed.</strong> Dates are <strong style="color:var(--mx-navy)">cutoff evidence</strong>: they show the procedure was performed during the audit period and before the report date, which matters for subsequent events and for whether a basis existed when the report was signed. Students undervalue dates because they look clerical, but an undated workpaper cannot be tied back to the report.<br /><br /><strong style="color:var(--mx-navy)">C. The name of the person who performed the audit work.</strong> Initialing the workpaper establishes <strong style="color:var(--mx-navy)">accountability</strong> and lets the reviewer judge whether the procedure was assigned to staff with the right competence. It is tempting to lump identity in with hours as firm paperwork, but identity is expressly required documentation while a timesheet is not.<br /><br /><strong style="color:var(--mx-navy)">D. The name of the person who reviewed the audit work.</strong> The reviewer's name and review date are the proof that <strong style="color:var(--mx-navy)">supervision and quality control</strong> actually happened. Some students assume review is evidenced only once, by the partner's sign-off on the engagement, but each workpaper carries its own evidence of who reviewed it and when.</p></div>`,},
    {
      id: "31050",
      prompt: `When establishing an understanding of the terms of an audit engagement with an issuer, an auditor should communicate which of the following to the audit committee?`,
      choices: [
        `The objective of the audit.`,
        `Critical accounting estimates.`,
        `The assessment of control risk.`,
        `The planned overall audit strategy.`,
      ],
      correctIndex: 0,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">A. The objective of the audit is correct.</strong> Establishing the terms of the engagement means agreeing on what the audit is for and who is responsible for what, before any work starts.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">For an issuer, the auditor must <strong style="color:var(--mx-navy)">establish an understanding of the terms of the engagement</strong> with the audit committee each year and record that understanding in an <strong style="color:var(--mx-navy)">engagement letter</strong>. Three items form the core: the <strong style="color:var(--mx-navy)">objective of the audit</strong> (expressing an opinion on the financial statements, and on internal control over financial reporting when that audit is also performed), the <strong style="color:var(--mx-navy)">auditor's responsibilities</strong>, and <strong style="color:var(--mx-navy)">management's responsibilities</strong>.</p><p style="margin:0 0 18px">The trap is timing. Every other choice here is something the auditor produces <strong style="color:var(--mx-navy)">by doing the audit</strong>, so none of it can exist when the terms are set. Ask yourself whether the item is an agreement about roles and goals, or an output of fieldwork. Only the first category belongs at the terms stage.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">B. Critical accounting estimates.</strong> This is a genuine required audit committee communication, which is exactly why students grab it. But the auditor's views on management's significant estimates come near the <strong style="color:var(--mx-navy)">conclusion of the audit</strong>, after testing the assumptions and data behind them. Nothing about those estimates is known when the engagement letter is signed.<br /><br /><strong style="color:var(--mx-navy)">C. The assessment of control risk.</strong> Control risk is an <strong style="color:var(--mx-navy)">internal judgment</strong> supported in the working papers, reached after understanding the entity and testing controls. Students confuse it with the discussion of significant risks that does get shared during planning. Handing the committee, and through it management, a tactical risk rating at the outset would also undercut the unpredictability of the audit.<br /><br /><strong style="color:var(--mx-navy)">D. The planned overall audit strategy.</strong> The overall strategy and timing are communicated to the audit committee, so this one feels right, but the communication occurs during the <strong style="color:var(--mx-navy)">planning phase</strong>, which follows the terms being set. A strategy requires preliminary risk assessment work the auditor has not yet performed.</p></div>`,},
    {
      id: "36050",
      prompt: `An auditor of a nonissuer is required to design and implement overall responses to address which type of assessed risk at the financial statement level?`,
      choices: [
        `Material weaknesses.`,
        `Fraud.`,
        `Noncompliance with laws and regulations.`,
        `Material misstatement.`,
      ],
      correctIndex: 3,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">D. Material misstatement is correct.</strong> Overall responses at the financial statement level are aimed at the assessed <strong style="color:var(--mx-navy)">risks of material misstatement</strong>, the broad category that covers both error and fraud.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">The auditor assesses the risk of material misstatement at two levels. Risks at the <strong style="color:var(--mx-navy)">financial statement level</strong> are <strong style="color:var(--mx-navy)">pervasive</strong>: they relate to the statements as a whole and could affect many assertions at once, such as a weak control environment or management with a motive to manipulate results. Because these risks cannot be pinned to one account, the auditor answers them with <strong style="color:var(--mx-navy)">overall responses</strong> that change how the whole engagement is run: assigning more experienced staff, increasing supervision, adding unpredictability to procedures, and emphasizing professional skepticism.</p><p style="margin:0 0 18px"><strong style="color:var(--mx-navy)">Assertion level</strong> risks attach to a specific class of transactions, account balance, or disclosure, and they are answered with <strong style="color:var(--mx-navy)">further audit procedures</strong>, meaning targeted tests of controls and substantive procedures. Watch the trigger words. Overall responses plus financial statement level always points to the assessed risk of material misstatement, the umbrella term that includes misstatement from both error and fraud.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. Material weaknesses.</strong> A <strong style="color:var(--mx-navy)">material weakness</strong> is a severe internal control deficiency, and identifying one triggers a communication to management and those charged with governance, not an audit strategy requirement. Students pick it because a weak control environment is the classic pervasive risk. The auditor responds to the assessed risk of misstatement that the weakness creates, and in a nonissuer audit there is no engagement to opine on internal control at all.<br /><br /><strong style="color:var(--mx-navy)">B. Fraud.</strong> This is the strongest distractor because <strong style="color:var(--mx-navy)">fraud risks</strong> are often pervasive and the auditor does respond to them at the financial statement level. But fraud is only one cause of misstatement, error being the other, so it sits inside the broader category the standards name. The requirement is written around the risk of material misstatement, not fraud alone.<br /><br /><strong style="color:var(--mx-navy)">C. Noncompliance with laws and regulations.</strong> This belongs to a separate set of procedures: inquiring of management about compliance, inspecting correspondence with regulators, and weighing direct versus indirect effects. It tempts students because noncompliance can be pervasive, but the response is specific procedures, not the overall responses required for financial statement level risk.</p></div>`,},
    {
      id: "340051",
      prompt: `Which of the following procedures is an accountant required to perform when reviewing the financial statements of a nonpublic entity in accordance with Statements on Standards for Accounting and Review Services (SSARS)?`,
      choices: [
        `Obtain an understanding of internal control.`,
        `Obtain a management representation letter.`,
        `Confirm cash balances with financial institutions.`,
        `Observe the inventory's physical count.`,
      ],
      correctIndex: 1,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">B. Obtain a management representation letter is correct.</strong> A written representation letter from management is a required closing step in every review engagement.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">A review provides <strong style="color:var(--mx-navy)">limited assurance</strong> that no material modifications should be made to the financial statements. The evidence comes almost entirely from <strong style="color:var(--mx-navy)">analytical procedures and inquiries</strong> of management, not from testing balances. Because the accountant verifies nothing independently, the written representations carry weight: they document that management accepts responsibility for the statements, has provided all relevant records, and has disclosed known fraud and subsequent events.</p><p style="margin:0 0 18px">The letter is required in <strong style="color:var(--mx-navy)">reviews and audits</strong>, but not in preparation or compilation engagements. It is dated no earlier than the date of the accountant's review report. If management <strong style="color:var(--mx-navy)">refuses to sign it</strong>, the accountant cannot complete the review and must withdraw.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. Obtain an understanding of internal control.</strong> That is a <strong style="color:var(--mx-navy)">risk assessment</strong> requirement in an audit, where controls drive the planned testing. Students are tempted because a review does require an understanding of the entity's industry, operations and accounting practices, which sounds close. A review stops short of controls: the accountant never evaluates their design or tests whether they operate.<br /><br /><strong style="color:var(--mx-navy)">C. Confirm cash balances with financial institutions.</strong> Confirmation is a <strong style="color:var(--mx-navy)">test of details</strong>, used in an audit to obtain evidence from a third party. It appeals because cash feels like something any engagement would verify. In a review the accountant may ask management about cash and run analytics on the balance, but gathering outside corroboration is not a required procedure.<br /><br /><strong style="color:var(--mx-navy)">D. Observe the inventory's physical count.</strong> Observation supports the <strong style="color:var(--mx-navy)">existence</strong> of inventory in an audit, and it is the step students memorize first, which makes it feel mandatory everywhere. Inventory being high risk does not change the engagement's scope. A review requires no counting, inspecting or observing: the accountant compares balances and turnover to expectations and asks management about unusual changes.</p></div>`,},
    {
      id: "34050",
      prompt: `An auditor determines that the client, a small manufacturing firm, has merged with another company. A portion of the manufacturing process has been moved to the merged company's plant site. Which of the following audit procedures is best to use to determine if the auditor's prior experience with the entity's operations is still relevant?`,
      choices: [
        `Perform analytical procedures on manufacturing costs to determine if costs have changed by a large amount.`,
        `Ask outside parties, such as the customers and suppliers, whether they have noticed any changes in manufacturing operations.`,
        `Ask senior management of the merged firm if changes in staff and manufacturing locations occurred.`,
        `Visit each manufacturing location to perform a walk-through of the manufacturing process, document the process, and compare to prior years.`,
      ],
      correctIndex: 3,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">D. Visit each manufacturing location to perform a walk-through of the manufacturing process, document the process, and compare to prior years is correct.</strong> Only firsthand observation of the new process shows how much of last year's understanding still applies.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Risk assessment requires an <strong style="color:var(--mx-navy)">understanding of the entity and its environment</strong>, including how transactions are initiated, processed and recorded. A merger that moves part of production to another site can change the <strong style="color:var(--mx-navy)">flow of transactions</strong>, the people performing controls and the documents generated, so prior-year knowledge has to be re-verified rather than assumed.</p><p style="margin:0 0 18px">A <strong style="color:var(--mx-navy)">walk-through</strong> is the strongest procedure here because it combines <strong style="color:var(--mx-navy)">observation, inspection and inquiry</strong> in a single pass. The auditor follows a transaction from initiation through to the general ledger at the new site, documents what actually happens, and compares it against the prior year's documentation. That direct comparison is exactly what the question asks for, and it is also how the auditor confirms that controls are <strong style="color:var(--mx-navy)">implemented</strong>, not merely described.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. Analytical procedures on manufacturing costs.</strong> Preliminary analytics are a legitimate risk assessment tool, which is why this feels responsive. But dollar variances show the financial result of a change, not the procedural steps behind it. Costs could swing on pricing alone while the process is untouched, or stay flat while the entire control structure was rebuilt.<br /><br /><strong style="color:var(--mx-navy)">B. Ask customers and suppliers.</strong> This confuses external confirmation, useful for balances such as receivables, with understanding internal operations. Outside parties see the shipping dock and the invoice, not the production flow, the segregation of duties, or the records kept at the plant. They cannot describe what the auditor needs to document.<br /><br /><strong style="color:var(--mx-navy)">C. Ask senior management about changes.</strong> Inquiry is a valid risk assessment procedure and is usually the starting point, which makes this tempting. The auditor already knows a merger and relocation occurred, so the answer adds nothing, and inquiry alone never establishes that a process or control operates as described. It must be corroborated by observation or inspection.</p></div>`,},
    {
      id: "310050",
      prompt: `Which of the following circumstances is the highest indicator of a potential material weakness in internal control over financial reporting?`,
      choices: [
        `A significant reduction in gross profit margins on numerous product lines.`,
        `The recording of a significant impairment for goodwill.`,
        `An increase in the processing time for customer orders.`,
        `The identification of fraud on the part of senior management.`,
      ],
      correctIndex: 3,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">D. The identification of fraud on the part of senior management is correct.</strong> Fraud by the people who set the tone at the top is treated as a strong indicator of a material weakness no matter how small the dollar amount.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">A <strong style="color:var(--mx-navy)">material weakness</strong> is a deficiency, or combination of deficiencies, that creates a <strong style="color:var(--mx-navy)">reasonable possibility</strong> that a material misstatement will not be prevented or detected on a timely basis. Auditing standards flag a short list of circumstances as <strong style="color:var(--mx-navy)">strong indicators</strong> that one exists: <strong style="color:var(--mx-navy)">any fraud by senior management</strong>, material or not; a <strong style="color:var(--mx-navy)">restatement</strong> of prior statements to correct a material misstatement; a material misstatement found by the auditor that the company's own controls missed; and ineffective audit committee oversight of financial reporting.</p><p style="margin:0 0 18px">Senior management sets the <strong style="color:var(--mx-navy)">tone at the top</strong> and can override the procedures everyone else follows. Fraud at that level is not one broken control, it is evidence that the <strong style="color:var(--mx-navy)">control environment</strong> itself has failed, which makes every control built on top of it unreliable. The dollar amount is irrelevant.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. A significant reduction in gross profit margins on numerous product lines.</strong> Falling margins are an operating and market result: higher input costs, price competition. Students pick this because declining margins are a textbook fraud <strong style="color:var(--mx-navy)">risk factor</strong> and a classic analytical procedure exception, so risk indicator gets confused with control failure. A risk factor tells the auditor to do more work; it does not show that a control broke down.<br /><br /><strong style="color:var(--mx-navy)">B. The recording of a significant impairment for goodwill.</strong> Impairment is a <strong style="color:var(--mx-navy)">measurement outcome</strong>, recognized when carrying amount exceeds fair value, and it tempts students because a large write-off suggests earlier estimates were too optimistic. Recording the charge shows the valuation process working. Only if the impairment forced a restatement, or exposed the absence of any impairment testing, would a weakness be indicated.<br /><br /><strong style="color:var(--mx-navy)">C. An increase in the processing time for customer orders.</strong> This is <strong style="color:var(--mx-navy)">operational efficiency</strong>, and it draws students who hear process breakdown and think control breakdown. Slower is not the same as inaccurate: unless orders go unrecorded or land in the wrong period, order speed does not touch the reliability of the financial statements.</p></div>`,},
    {
      id: "328050",
      prompt: `In which of the following circumstances would an auditor most likely decide that direct access to a nonissuer entity's records held at a service organization is necessary?`,
      choices: [
        `The service organization processes material transactions for the user entity.`,
        `The service organization maintains material elements of the accounting records of the user entity.`,
        `The service organization provides a type 2 report, but not a type 1 report.`,
        `The service organization provides a material dollar amount of services to the user entity.`,
      ],
      correctIndex: 1,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">B. The service organization maintains material elements of the accounting records of the user entity is correct.</strong> When the client's books physically live at the service provider, the auditor has to go where the records are.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">When a client outsources part of its accounting, the user auditor still needs evidence about the transactions and balances the service produces. The normal order is to test the <strong style="color:var(--mx-navy)">user entity's own controls</strong> over data sent to and received from the provider, then to obtain a <strong style="color:var(--mx-navy)">SOC 1 report</strong> from the service auditor. <strong style="color:var(--mx-navy)">Direct access</strong> is the fallback when neither route reaches the underlying audit trail.</p><p style="margin:0 0 18px">That gap is widest when the provider holds the <strong style="color:var(--mx-navy)">records themselves</strong>: the general ledger, journals or subsidiary files supporting the balances. Nothing at the client's office reproduces them, so the auditor must reach the host system to inspect source data, follow the trail and pull samples. The trigger is the <strong style="color:var(--mx-navy)">nature of the records held</strong>, not the size of the contract.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. Processes material transactions.</strong> This describes nearly every service organization, from payroll bureaus to cloud billing, which is why it feels like the safe pick. <strong style="color:var(--mx-navy)">Processing alone</strong> leaves the client holding input documents and output reports, so the auditor can test those locally and reconcile them to independent evidence such as bank statements.<br /><br /><strong style="color:var(--mx-navy)">C. Provides a type 2 report, but not a type 1 report.</strong> This reverses the hierarchy. A <strong style="color:var(--mx-navy)">type 2 report</strong> covers design, implementation and operating effectiveness over a period, while a type 1 covers only design and implementation at a point in time, so a type 2 is the stronger evidence. It reduces the need to go to the provider; the <strong style="color:var(--mx-navy)">absence of a usable report</strong> is what pushes an auditor there.<br /><br /><strong style="color:var(--mx-navy)">D. Provides a material dollar amount of services.</strong> Fee size is not the test, though it borrows the language of materiality and sounds quantitative. A client can pay enormous sums for outsourced facilities, security or logistics without any of it touching the <strong style="color:var(--mx-navy)">information system relevant to financial reporting</strong>.</p></div>`,},
    {
      id: "38050",
      prompt: `Which of the following statements regarding fraud is not correct?`,
      choices: [
        `Authenticating signatures and validating electronic disbursement authorizations is typically performed by an auditor.`,
        `Misrepresenting information in response to inquiries may conceal an improper transaction.`,
        `Management frequently has the ability to manipulate accounting records.`,
        `Management may be able to override a control that otherwise appears to be operating effectively.`,
      ],
      correctIndex: 0,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">A. Authenticating signatures and validating electronic disbursement authorizations is typically performed by an auditor is correct.</strong> An auditor is not a document examiner, so this is the false statement the question is hunting for.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">An audit is planned to obtain <strong style="color:var(--mx-navy)">reasonable assurance</strong> that the statements are free of material misstatement from error or fraud. The auditor applies <strong style="color:var(--mx-navy)">professional skepticism</strong> and may treat records as genuine unless evidence suggests otherwise. The auditor is <strong style="color:var(--mx-navy)">not trained as a forensic document examiner</strong> and is not expected to authenticate handwriting or validate the cryptography behind an electronic approval.</p><p style="margin:0 0 18px">The other three choices describe the <strong style="color:var(--mx-navy)">inherent limitations</strong> that make fraud harder to detect than error: false responses to inquiry, management's access to the records, and <strong style="color:var(--mx-navy)">management override</strong>. Those are true statements, which is why they are wrong answers on a "not correct" question. Read the stem twice before you pick.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">B. Misrepresenting information in response to inquiries may conceal an improper transaction.</strong> This is a true statement about <strong style="color:var(--mx-navy)">concealment</strong>, and it is exactly why inquiry alone is weak evidence. Students hesitate because it sounds like an accusation against management rather than a standard, but the standards openly list false or incomplete responses as a reason fraud goes undetected.<br /><br /><strong style="color:var(--mx-navy)">C. Management frequently has the ability to manipulate accounting records.</strong> True, and it is the reason <strong style="color:var(--mx-navy)">journal entry testing</strong> and the review of estimates for bias are required in every audit. The word "frequently" tempts students to call it an overstatement, but the point is about access and opportunity, not about how often managers actually cheat.<br /><br /><strong style="color:var(--mx-navy)">D. Management may be able to override a control that otherwise appears to be operating effectively.</strong> This is the classic <strong style="color:var(--mx-navy)">inherent limitation of internal control</strong>. It feels contradictory, since a control that can be bypassed hardly seems effective, and that is the confusion being tested: the control can operate as designed for routine transactions while senior management still steps around it.</p></div>`,},
    {
      id: "311050",
      prompt: `For which of the following circumstances occurring during an audit of a nonissuer would an auditor most likely revise the initial determination of materiality for the financial statements as a whole?`,
      choices: [
        `The auditor discovers fewer misstatements than expected in substantive tests of a class of transactions.`,
        `The client entity disposes of a significant part of the entity's business.`,
        `The client entity adopts a new accounting standard.`,
        `The auditor is unable to obtain sufficient, relevant audit evidence for a significant account balance.`,
      ],
      correctIndex: 1,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">B. The client entity disposes of a significant part of the entity's business is correct.</strong> Selling off a large piece of the business shrinks the benchmark that materiality was built on, so the number has to be recalculated.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Materiality for the financial statements as a whole is a <strong style="color:var(--mx-navy)">planning estimate, not a fixed figure</strong>. It is normally a percentage of a <strong style="color:var(--mx-navy)">benchmark</strong> such as total revenue, total assets or pretax income. The auditor must revise it whenever information surfaces during the audit that would have produced a different amount had it been known at the start.</p><p style="margin:0 0 18px">A <strong style="color:var(--mx-navy)">significant disposal</strong> is the classic trigger because it changes the size of the entity itself. Materiality set on the pre-disposal company is now too high, so a misstatement that once looked trivial may be material to the smaller remaining operations. Lowering overall materiality also lowers <strong style="color:var(--mx-navy)">performance materiality</strong>, which usually means larger samples and more extensive procedures. Events that change only how the audit is run or how the report reads do not move the benchmark.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. Fewer misstatements than expected in substantive tests.</strong> This belongs to the assessment of <strong style="color:var(--mx-navy)">detection risk and sample sizes</strong>, not to materiality. It tempts students because the auditor genuinely does update the plan as results come in. But clean results say something about how well the client's processes operate, not about the size of the entity, so the benchmark is untouched.<br /><br /><strong style="color:var(--mx-navy)">C. The client adopts a new accounting standard.</strong> Adoption changes recognition, measurement or disclosure for particular items, and it is tempting because the financial statements visibly change. The link is not automatic: materiality moves only if the <strong style="color:var(--mx-navy)">benchmark itself moves</strong>. Unless adoption dramatically restates revenue, assets or income, the original threshold still fits.<br /><br /><strong style="color:var(--mx-navy)">D. Unable to obtain sufficient, relevant evidence for a significant balance.</strong> That is a <strong style="color:var(--mx-navy)">scope limitation</strong>, and it drives the opinion: qualified or a disclaimer depending on pervasiveness. Students confuse "this is a serious audit problem" with "this changes materiality." Missing evidence limits what the auditor can conclude, but the benchmark amounts used to set the threshold are exactly what they were.</p></div>`,},
    {
      id: "322050",
      prompt: `When is it most appropriate for an auditor to determine tolerable misstatement?`,
      choices: [
        `When assessing the entity's internal control.`,
        `When confirmation procedures cannot be performed.`,
        `When planning a sampling procedure for a class of transactions.`,
        `When determining materiality for the financial statements as a whole.`,
      ],
      correctIndex: 2,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">C. When planning a sampling procedure for a class of transactions is correct.</strong> Tolerable misstatement is an input to sample design, so the auditor sets it while building the test.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Tolerable misstatement is <strong style="color:var(--mx-navy)">performance materiality applied to one sampling application</strong>. It is the largest monetary error the auditor is willing to accept in a specific account balance or class of transactions while still concluding that the financial statements are not materially misstated. It has to exist before the sample is pulled, because it drives the <strong style="color:var(--mx-navy)">sample size</strong> and later becomes the benchmark against which the <strong style="color:var(--mx-navy)">projected misstatement</strong> is measured.</p><p style="margin:0 0 18px">The order of the judgments matters. <strong style="color:var(--mx-navy)">Overall materiality</strong> for the financial statements comes first, <strong style="color:var(--mx-navy)">performance materiality</strong> is set below it as a buffer, and tolerable misstatement is then assigned to each individual substantive test. The relationship to sample size is <strong style="color:var(--mx-navy)">inverse</strong>: a lower tolerable misstatement demands a larger sample, because the auditor is leaving less room for error.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. When assessing the entity's internal control.</strong> Control testing uses attribute sampling, where the planning threshold is the <strong style="color:var(--mx-navy)">tolerable rate of deviation</strong>, a percentage of the population, not a dollar amount. Students pick this because both limits are called tolerable and both are set during planning. A control either operated or it did not, so the output is a deviation rate, not a misstatement measured in dollars.<br /><br /><strong style="color:var(--mx-navy)">B. When confirmation procedures cannot be performed.</strong> Non-responses create a need for <strong style="color:var(--mx-navy)">alternative procedures</strong> such as examining subsequent cash receipts or shipping documents, and an inability to apply any procedure is treated as a misstatement in the sample. This tempts students because unexamined items feel like they should reset the threshold. The threshold was already fixed when the sample was designed, and nothing about a failed confirmation changes it.<br /><br /><strong style="color:var(--mx-navy)">D. When determining materiality for the financial statements as a whole.</strong> That is the top-down, statement-level number driving the opinion, and it is the source from which tolerable misstatement is eventually derived, which is exactly why the option looks right. But it is a separate and <strong style="color:var(--mx-navy)">earlier judgment</strong>, made before any specific class of transactions is chosen for sampling.</p></div>`,},
    {
      id: "31051",
      prompt: `Which of the following best supports the auditor's judgment to use audit evidence obtained in a previous audit about the operating effectiveness of a particular control?`,
      choices: [
        `The auditor does not plan to put significant reliance on the control.`,
        `The company has hired several new employees who have gone through extensive training.`,
        `The control has been strengthened from the period before.`,
        `The auditor worked on the previous audit engagement.`,
      ],
      correctIndex: 0,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">A. The auditor does not plan to put significant reliance on the control is correct.</strong> Prior-period evidence is available only when the current audit is not leaning heavily on that control.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">An auditor may <strong style="color:var(--mx-navy)">reuse evidence</strong> about a control's operating effectiveness from an earlier audit only when the control <strong style="color:var(--mx-navy)">has not changed</strong> since it was last tested and it does not address a <strong style="color:var(--mx-navy)">significant risk</strong>. Even then the evidence has a shelf life: the control must be tested at least <strong style="color:var(--mx-navy)">once every third audit</strong>, so it can never sit untested for more than two years.</p><p style="margin:0 0 18px">The deciding factor is how much weight the current audit places on the control. If the auditor plans <strong style="color:var(--mx-navy)">significant reliance</strong> in order to cut substantive testing, or the control mitigates a significant risk such as fraud, prior-year work will not do and the control must be tested this year. <strong style="color:var(--mx-navy)">Low planned reliance</strong> removes that barrier.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">B. The company has hired several new employees who have gone through extensive training.</strong> Turnover is a change in how the control is carried out day to day, and training says nothing about whether the new staff actually perform it. Students are tempted because training sounds like a reason for more confidence, but confidence in people is not evidence about the control's operation. <strong style="color:var(--mx-navy)">New personnel</strong> push the auditor toward current-year testing, not away from it.<br /><br /><strong style="color:var(--mx-navy)">C. The control has been strengthened from the period before.</strong> This is the trap. Improvement feels like it should make old evidence safer, but strengthening is still a <strong style="color:var(--mx-navy)">change</strong>, and prior testing describes a control that no longer exists. A modified control requires fresh evaluation of its <strong style="color:var(--mx-navy)">design, implementation and operating effectiveness</strong> this period.<br /><br /><strong style="color:var(--mx-navy)">D. The auditor worked on the previous audit engagement.</strong> This confuses the auditor's <strong style="color:var(--mx-navy)">familiarity with the client</strong> with evidence about the client. Continuity may help the auditor spot changes in the control environment quickly, but personal memory of last year's testing proves nothing about how the control ran this year. The decision turns on the control and the risk, not on who staffed the file.</p></div>`,},
    {
      id: "35050",
      prompt: `Under which of the following circumstances is an auditor considered to be using the work of an external specialist?`,
      choices: [
        `A real estate appraiser evaluates the fair market value of real estate.`,
        `A city tax assessor's notice shows tax that the company has not accrued.`,
        `An attorney for the client interprets pending litigation in the attorney's letter.`,
        `A company plant manager evaluates whether computer parts inventory is obsolete.`,
      ],
      correctIndex: 0,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">A. A real estate appraiser evaluates the fair market value of real estate is correct.</strong> Appraising property calls for expertise outside accounting and auditing, so the auditor leans on an outside expert to obtain evidence.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">An <strong style="color:var(--mx-navy)">auditor's specialist</strong> is a person or firm with expertise in a field <strong style="color:var(--mx-navy)">other than accounting or auditing</strong> whose work the auditor uses to obtain audit evidence. <strong style="color:var(--mx-navy)">External</strong> means the specialist is not a partner or employee of the audit firm. Real estate valuation requires appraisal training and market data auditors do not have, so an independent appraiser brought in to test management's carrying value fits squarely.</p><p style="margin:0 0 18px">Two questions sort these fact patterns. First, <strong style="color:var(--mx-navy)">who engaged the expert</strong>: an expert hired by the client to help prepare the numbers is <strong style="color:var(--mx-navy)">management's specialist</strong>, and that output is client-generated evidence the auditor tests. Second, is the auditor using outside expertise or simply performing a <strong style="color:var(--mx-navy)">routine procedure</strong>: inspecting a document or sending a required confirmation is ordinary evidence gathering, however expert the person on the other end.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">B. A city tax assessor's notice shows tax that the company has not accrued.</strong> This is routine substantive testing of <strong style="color:var(--mx-navy)">accrued liabilities</strong> using an external source document. Students are tempted because an assessor does value property for a living. But the auditor engaged no one; inspecting an existing notice is document inspection pointing to an unrecorded liability.<br /><br /><strong style="color:var(--mx-navy)">C. An attorney for the client interprets pending litigation in the attorney's letter.</strong> The classic trap: the attorney does hold expertise outside accounting, and lawyers feel like specialists. The <strong style="color:var(--mx-navy)">legal inquiry letter</strong> is a required procedure used to corroborate management's assertions about loss contingencies, and the attorney works for the client, not the audit team. It is classified as an <strong style="color:var(--mx-navy)">external confirmation</strong>.<br /><br /><strong style="color:var(--mx-navy)">D. A company plant manager evaluates whether computer parts inventory is obsolete.</strong> The manager is a client employee, so his judgment is a <strong style="color:var(--mx-navy)">management estimate</strong> the auditor must challenge and test. Students see technical knowledge and read specialist, but even an outsider hired by the client would be management's specialist rather than the auditor's.</p></div>`,},
    {
      id: "326050",
      prompt: `Which of the following statements describes the auditor's responsibility with regard to accounting estimates?`,
      choices: [
        `The auditor is responsible for revising past accounting estimates.`,
        `The auditor should revise, test, and approve the process used by management to develop estimates.`,
        `The auditor is responsible for calculating the accounting estimates used in the financial statements.`,
        `The auditor is responsible for evaluating the reasonableness of management's accounting estimates.`,
      ],
      correctIndex: 3,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">D. The auditor is responsible for evaluating the reasonableness of management's accounting estimates is correct.</strong> The estimate belongs to management; the auditor's job is to decide whether the recorded amount is reasonable.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Estimates such as the allowance for doubtful accounts, warranty liabilities, obsolescence reserves and fair value measurements cannot be measured precisely. <strong style="color:var(--mx-navy)">Management selects the method, data and assumptions</strong> and records the number. The auditor obtains sufficient appropriate evidence to conclude whether that amount is <strong style="color:var(--mx-navy)">reasonable</strong> under the applicable reporting framework and free of material misstatement, staying alert for <strong style="color:var(--mx-navy)">management bias</strong>.</p><p style="margin:0 0 18px">There are three ways to do that evaluation: <strong style="color:var(--mx-navy)">test management's process</strong>, <strong style="color:var(--mx-navy)">develop an independent expectation</strong> to compare against the recorded figure, or <strong style="color:var(--mx-navy)">review subsequent events</strong> such as actual settlements or defaults. All three are evaluation techniques. None of them moves ownership of the estimate to the auditor, because performing a management function <strong style="color:var(--mx-navy)">impairs independence</strong>.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. The auditor is responsible for revising past accounting estimates.</strong> This confuses the auditor's ability to <strong style="color:var(--mx-navy)">propose</strong> an adjustment with authority to make one. Students are tempted because auditors do accumulate and communicate misstatements, but management decides whether to record the change. An estimate that was reasonable when made is also not rewritten with hindsight.<br /><br /><strong style="color:var(--mx-navy)">B. The auditor should revise, test, and approve the process used by management to develop estimates.</strong> This is half right, which is what makes it dangerous: testing management's process is one of the three approaches. The words "revise" and "approve" push the auditor into designing and blessing a client process. Auditors evaluate the process; they do not own or sign off on it.<br /><br /><strong style="color:var(--mx-navy)">C. The auditor is responsible for calculating the accounting estimates used in the financial statements.</strong> This borrows from the independent expectation approach, where the auditor does compute a figure. That computation is <strong style="color:var(--mx-navy)">audit evidence for comparison</strong>, never the amount booked. If the auditor's number becomes the recorded balance, the auditor is auditing personal work, a <strong style="color:var(--mx-navy)">self-review threat</strong>.</p></div>`,},
    {
      id: "34051",
      prompt: `An auditor ordinarily reviews the board of directors' meeting minutes to identify which of the following engagement planning issues?`,
      choices: [
        `Preliminary judgment about materiality.`,
        `Subsequent events.`,
        `Competence of internal audit staff.`,
        `Related party transactions.`,
      ],
      correctIndex: 3,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">D. Related party transactions is correct.</strong> Board minutes are where dealings with insiders get formally authorized and recorded.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Reading the minutes of stockholder, board and key committee meetings is a <strong style="color:var(--mx-navy)">required risk assessment procedure during planning</strong>. Minutes are the official record of high-level authorizations: material contracts, financing arrangements, acquisitions, dividend declarations, and transactions with <strong style="color:var(--mx-navy)">principal owners, officers and entities they control</strong>. Because deals of that kind must be approved at board level, the minutes are the single most reliable place to spot them early.</p><p style="margin:0 0 18px">Timing matters. Related party transactions carry <strong style="color:var(--mx-navy)">high inherent risk</strong> because they are not negotiated at arm's length, so identifying them in planning lets the auditor build targeted procedures into the audit program. Minutes are read again at the end of the engagement, but for a <strong style="color:var(--mx-navy)">different purpose</strong>.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. Preliminary judgment about materiality.</strong> Materiality is the <strong style="color:var(--mx-navy)">auditor's own judgment</strong>, set from quantitative benchmarks such as a percentage of pretax income, total assets or revenue, then adjusted for qualitative factors. Students take the bait because materiality genuinely is a planning decision and this question is about planning. The board does not set the auditor's threshold, and no amount of reading minutes produces that number.<br /><br /><strong style="color:var(--mx-navy)">B. Subsequent events.</strong> This is the timeline trap, and it tempts strong students because auditors really do read minutes looking for subsequent events. That reading belongs to the <strong style="color:var(--mx-navy)">concluding phase</strong>, scanning post balance sheet meetings for settled lawsuits, casualties or new financing that require adjustment or disclosure. The question asks what planning issue the review addresses, so this is the wrong phase.<br /><br /><strong style="color:var(--mx-navy)">C. Competence of internal audit staff.</strong> Competence is assessed from the internal auditors' education, certifications, experience, training and the quality of their working papers and reports. The confusion is that the board or audit committee oversees internal audit, so the function's <strong style="color:var(--mx-navy)">reporting line</strong> does surface in governance records. Reporting lines speak to objectivity, not skill, and routine minutes will not tell you whether the staff can do the work.</p></div>`,},
    {
      id: "323050",
      prompt: `An auditor of a nonissuer's financial statements obtained scanned versions of executed sales contracts from the nonissuer's sales department. The auditor has not tested the operating effectiveness of the controls around the execution of the original contracts. In order to validate the reliability of the scanned contracts that the auditor plans to use as audit evidence, the auditor would most appropriately`,
      choices: [
        `Confirm the key terms of the contracts with the customer.`,
        `Compare the customer names on the scanned contracts to the nonissuer's authorized customer list.`,
        `Perform inquiries with the nonissuer's information technology specialist to confirm that the scanned contracts are not stored in a remote server.`,
        `Perform inquiries with the sales manager to determine whether the scanned contracts are structured in accordance with the nonissuer's revenue recognition policies.`,
      ],
      correctIndex: 0,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">A. Confirm the key terms of the contracts with the customer is correct.</strong> Evidence from an independent outside party is the only way to validate documents whose underlying controls the auditor has not tested.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Evidence is more reliable when it comes from a source <strong style="color:var(--mx-navy)">outside the client</strong> and when the auditor obtains it directly. A scanned contract is a <strong style="color:var(--mx-navy)">copy, not an original</strong>, and the auditor has not tested the controls over how the originals were executed or how the images were created. Authenticity and completeness therefore rest on the client's unverified processes, so the scans cannot stand on their own.</p><p style="margin:0 0 18px">The fix is to corroborate the terms with an independent party. <strong style="color:var(--mx-navy)">Confirming key terms with the customer</strong> establishes that the agreement exists and that the terms shown in the scan match reality, which is exactly the assurance an untested control environment cannot supply. Watch the pattern: when <strong style="color:var(--mx-navy)">control risk is at the maximum</strong>, the auditor shifts the <strong style="color:var(--mx-navy)">nature</strong> of testing toward externally sourced evidence rather than doing more internal tie-outs.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">B. Compare customer names to the authorized customer list.</strong> This is an <strong style="color:var(--mx-navy)">internal tie-out</strong> against records that are just as unverified as the scans. It attracts students because it looks like real documentary testing, but a client-generated list cannot authenticate a client-generated document, and a matching name says nothing about pricing, quantities or terms.<br /><br /><strong style="color:var(--mx-navy)">C. Inquire whether the scans are stored on a remote server.</strong> Storage location is a <strong style="color:var(--mx-navy)">general IT infrastructure</strong> question, not a reliability procedure. The word "scanned" pushes students toward IT controls and remote hosting sounds risky, but a file kept on site can be altered just as easily, and the inquiry never touches the contents of the contract.<br /><br /><strong style="color:var(--mx-navy)">D. Inquire with the sales manager about revenue recognition policies.</strong> This is <strong style="color:var(--mx-navy)">inquiry of the very department that produced the documents</strong>, the weakest evidence available. It also answers the wrong question: whether the terms are accounted for correctly is separate from whether the scanned document is genuine and unaltered.</p></div>`,},
    {
      id: "322051",
      prompt: `An auditor of a nonissuer plans to confirm a sample of accounts receivable to obtain audit evidence about whether the population of accounts receivable is accurately stated. When designing the audit sample, the auditor should do which of the following?`,
      choices: [
        `Select the accounts for confirmation using a statistical sampling approach in order to minimize nonsampling risk.`,
        `Perform audit procedures to obtain evidence that the population from which the audit sample is drawn is complete.`,
        `Stratify the population from which the sample will be drawn to ensure that proportional samples are drawn from each level of accounts receivable.`,
        `Use automated data analytics to identify and select accounts for confirmation that do not correspond to the characteristics of the population of accounts receivable.`,
      ],
      correctIndex: 1,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">B. Perform audit procedures to obtain evidence that the population from which the audit sample is drawn is complete is correct.</strong> A sample speaks only for the items on the list it came from.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Sampling projects the results of a few selected items onto an entire balance, so the conclusion is only as reliable as the <strong style="color:var(--mx-navy)">sampling frame</strong>, the listing those items came from. Before selecting anything, the auditor obtains evidence that the receivable listing is <strong style="color:var(--mx-navy)">complete</strong>, usually by footing the subsidiary ledger and agreeing it to the general ledger control account. If three large customers were never posted, no sample size and no selection method will reach them.</p><p style="margin:0 0 18px">That step is required whether the sample is <strong style="color:var(--mx-navy)">statistical or nonstatistical</strong>. Selection technique answers how items are chosen; completeness answers whether everything that belongs in the population is actually in it. A flawless sample drawn from an incomplete list leaves the <strong style="color:var(--mx-navy)">understatement undetected</strong>.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. Select the accounts using a statistical sampling approach to minimize nonsampling risk.</strong> Statistical sampling measures and controls <strong style="color:var(--mx-navy)">sampling risk</strong>, the risk that a sample is not representative. Students pick it because statistical sounds more rigorous. <strong style="color:var(--mx-navy)">Nonsampling risk</strong> comes from human performance: misreading a confirmation reply, using the wrong procedure, missing an error on an invoice. It is reduced by planning, supervision and review, never by the selection method.<br /><br /><strong style="color:var(--mx-navy)">C. Stratify to ensure proportional samples from each level.</strong> Stratification is a real, often efficient technique for receivables, which is why this reads like textbook language. The flaw is proportional: allocation among strata is deliberately <strong style="color:var(--mx-navy)">disproportional</strong>, with the largest accounts often confirmed 100% while hundreds of small accounts yield only a few items. Stratification is also an efficiency choice, not a design requirement.<br /><br /><strong style="color:var(--mx-navy)">D. Use data analytics to select accounts that do not correspond to the population.</strong> Deliberately selecting accounts that do not match the population's characteristics is a <strong style="color:var(--mx-navy)">judgmental test of unusual items</strong>, not audit sampling. Data analytics sounds modern and exception hunting feels aggressive. But the objective here is a conclusion about the whole population, and results from hand-picked anomalies cannot be <strong style="color:var(--mx-navy)">projected</strong> to the balance.</p></div>`,},
    {
      id: "317050",
      prompt: `An auditor entered a nonissuer's relevant fixed asset information for 10 fixed assets into a spreadsheet and used the spreadsheet program to compute depreciation expense for those assets for the fiscal year. The auditor then compared the computed depreciation expense amounts to the amounts recorded by management. Which of the following types of audit procedures did the auditor perform to obtain evidence?`,
      choices: [
        `Inspection.`,
        `Confirmation.`,
        `Recalculation.`,
        `Analytical procedures.`,
      ],
      correctIndex: 2,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">C. Recalculation is correct.</strong> The auditor independently redid management's depreciation math and compared the results, which is a test of mathematical accuracy.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Recalculation means <strong style="color:var(--mx-navy)">checking the mathematical accuracy of documents or records</strong>. The auditor takes the client's own inputs, here cost, useful life, salvage value and date placed in service, runs the computation independently, and compares the answer to the amount recorded. The tool is irrelevant: a spreadsheet, a calculator or audit software all produce the same kind of evidence, an <strong style="color:var(--mx-navy)">auditor generated computation</strong> supporting accuracy and valuation.</p><p style="margin:0 0 18px">The trap is scope. This work was done <strong style="color:var(--mx-navy)">asset by asset on 10 specific items</strong>, and precise item level math is always recalculation. When an auditor instead builds an expectation from relationships in aggregate data, such as a total cost pool times an average rate, and asks whether the recorded total looks reasonable, that is an analytical procedure. <strong style="color:var(--mx-navy)">Precision versus expectation</strong> is the dividing line.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. Inspection.</strong> Inspection is <strong style="color:var(--mx-navy)">examining records or documents, or physically examining a tangible asset</strong>. It would fit if the auditor walked the plant floor to trace machines to the asset ledger, or pulled vendor invoices and titles to support recorded cost. Students pick it because the auditor did have to read the asset records to get the inputs, but gathering inputs is setup; the evidence came from the computation, not from looking at the document.<br /><br /><strong style="color:var(--mx-navy)">B. Confirmation.</strong> Confirmation is a <strong style="color:var(--mx-navy)">direct written response from an independent outside party</strong>. It would apply if some machines sat at a third party warehouse and the auditor wrote to the custodian to verify quantity and ownership. Nothing here left the client: the inputs came from client records and the answer came from the auditor's own spreadsheet, so no external party ever responded.<br /><br /><strong style="color:var(--mx-navy)">D. Analytical procedures.</strong> Analytical procedures evaluate <strong style="color:var(--mx-navy)">plausible relationships</strong> among financial and nonfinancial data to develop an expectation of a recorded amount. The spreadsheet tempts students into calling this data analytics, but a formula is not an estimate. The auditor computed the exact depreciation due on each of 10 assets rather than predicting a total, so this is precise math, not a reasonableness test.</p></div>`,},
    {
      id: "39050",
      prompt: `A CPA who was auditing a client's cellular telephone bills discovered a substantial expense increase over the previous year. To identify this situation, the CPA would have initially performed which of the following procedures?`,
      choices: [
        `Analytical procedures for cellular phone expense.`,
        `Reading the cellular phone contract for each phone.`,
        `Interviewing the accounts receivable clerk who has responsibility for cellular phone usage.`,
        `Examining the cellular phone provider's web site.`,
      ],
      correctIndex: 0,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">A. Analytical procedures for cellular phone expense is correct.</strong> Comparing this year's balance to last year's is the classic analytical procedure, and that comparison is what surfaced the increase.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Analytical procedures test an account by comparing the recorded amount to an <strong style="color:var(--mx-navy)">expectation</strong> built from prior periods, budgets, industry data or non-financial data such as headcount or number of handsets. A straight <strong style="color:var(--mx-navy)">year over year comparison</strong> of an expense account is the most common form. Its job is to <strong style="color:var(--mx-navy)">flag</strong> an unusual fluctuation, not to explain it.</p><p style="margin:0 0 18px">Sequence is what this question tests. Analytics come <strong style="color:var(--mx-navy)">first</strong> because they are cheap and cover the entire balance. Once a variance is identified, the auditor moves to <strong style="color:var(--mx-navy)">tests of details</strong>, inspecting contracts, invoices and payments to find the cause. The other three choices are all investigative follow up steps that only make sense after someone has already noticed the increase.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">B. Reading the cellular phone contract for each phone.</strong> This is a <strong style="color:var(--mx-navy)">test of details</strong>, the natural second step once a variance appears. It tempts students because the contract does eventually explain the increase: rate changes, added lines, overage charges. But reading every contract on an account nobody has flagged is inefficient, and the procedure never compares one year to another, so it cannot be what revealed the jump.<br /><br /><strong style="color:var(--mx-navy)">C. Interviewing the accounts receivable clerk who has responsibility for cellular phone usage.</strong> <strong style="color:var(--mx-navy)">Inquiry</strong> corroborates a variance, it does not detect one, and a clerk's explanation is weak evidence until the auditor has measured the change. The choice also misplaces the account: phone bills are an expense settled through accounts payable, not a receivable.<br /><br /><strong style="color:var(--mx-navy)">D. Examining the cellular phone provider's web site.</strong> <strong style="color:var(--mx-navy)">External data</strong> can help build an expectation, published rate plans for instance, which is why this feels analytical. A vendor's public site shows marketing prices, not what this client was billed and recorded, so it says nothing about the movement in the client's general ledger where the increase actually appeared.</p></div>`,},
    {
      id: "314050",
      prompt: `An auditor reviews a sample of confirmed accounts receivable. Some of the accounts selected did not reply. Which of the following procedures provides the best evidence for the existence of an accounts receivable balance for which a positive confirmation request was not returned by the customer?`,
      choices: [
        `Examine subsequent cash receipts.`,
        `Discuss the customer's credit history with the client.`,
        `Compare the customer's year-end accounts receivable balance to the prior year-end balance.`,
        `Ask the accounts receivable clerk about the accuracy of the balance.`,
      ],
      correctIndex: 0,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">A. Examine subsequent cash receipts is correct.</strong> Cash paid by the customer after year end proves the customer really owed the money on the balance sheet date.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">A <strong style="color:var(--mx-navy)">positive confirmation</strong> that comes back blank cannot be dropped from the sample or treated as agreement. The auditor must perform <strong style="color:var(--mx-navy)">alternative procedures</strong> on every nonresponse, and the premier alternative for the <strong style="color:var(--mx-navy)">existence</strong> assertion is examining <strong style="color:var(--mx-navy)">subsequent cash receipts</strong>: match the January deposit to the December invoice using the remittance advice and the bank statement.</p><p style="margin:0 0 18px">That evidence is strong because it is <strong style="color:var(--mx-navy)">externally generated</strong>. The customer moved its own money to settle a specific invoice, which is conduct no client entry can fabricate. If the account is still unpaid when fieldwork ends, the auditor drops to <strong style="color:var(--mx-navy)">shipping documents</strong> and then sales invoices, which support the sale but are weaker because they originate inside the client.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">B. Discuss the customer's credit history with the client.</strong> Credit history speaks to <strong style="color:var(--mx-navy)">collectibility and the allowance</strong>, which is a valuation question, not an existence question. Students pick it because it sounds like evidence about the customer, but it is really inquiry of client staff about a customer's general payment habits and says nothing about whether this specific balance was owed at year end.<br /><br /><strong style="color:var(--mx-navy)">C. Compare the customer's year-end accounts receivable balance to the prior year-end balance.</strong> That is an <strong style="color:var(--mx-navy)">analytical procedure</strong>, useful for risk assessment across an aggregate population. It tempts because a numeric comparison feels objective, but both figures come from the client's own ledger, and a fictitious balance that repeats year after year would look perfectly consistent.<br /><br /><strong style="color:var(--mx-navy)">D. Ask the accounts receivable clerk about the accuracy of the balance.</strong> Inquiry of client personnel is a legitimate procedure, which is why it draws votes, but it is the <strong style="color:var(--mx-navy)">weakest form of evidence</strong> and must be corroborated. Here the clerk is the same source that produced the recorded balance, so the answer adds no independent support for existence.</p></div>`,},
    {
      id: "326051",
      prompt: `When an auditor is performing an audit of an issuer, each of the following is sufficient for evaluating the reasonableness of significant accounting estimates, except`,
      choices: [
        `Reviewing and testing the process used by management to develop the estimate.`,
        `Reviewing the testing of significant estimates performed by the entity's internal auditors.`,
        `Reviewing subsequent events or transactions occurring prior to the date of the auditor's report.`,
        `Developing an independent expectation of the estimate to corroborate the reasonableness of management's estimate.`,
      ],
      correctIndex: 1,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">B. Reviewing the testing of significant estimates performed by the entity's internal auditors is correct.</strong> Internal audit work can inform the audit, but it is not one of the approaches that by itself supports a conclusion on a significant estimate.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">To evaluate a significant accounting estimate, the auditor uses one or a combination of <strong style="color:var(--mx-navy)">three approaches</strong>: <strong style="color:var(--mx-navy)">test management's process</strong> for developing the estimate, <strong style="color:var(--mx-navy)">develop an independent expectation</strong> to compare against management's number, or <strong style="color:var(--mx-navy)">review subsequent events and transactions</strong> occurring before the report date. Any of the three, applied properly, can produce sufficient evidence.</p><p style="margin:0 0 18px">Internal audit is not on that list. Internal auditors are <strong style="color:var(--mx-navy)">employees of the entity</strong>, so their conclusions are not a substitute for the external auditor's own work. The auditor may use internal audit's work as one input, but only after evaluating their competence and objectivity and testing some of what they did, and <strong style="color:var(--mx-navy)">responsibility for the opinion is never shared</strong>. On a high risk estimate, reading their testing and stopping there leaves the auditor with no direct evidence.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. Reviewing and testing the process used by management.</strong> This is the most common of the three approaches. Students distrust it because it begins with management's own model, but the auditor independently tests the underlying data, evaluates whether the assumptions are reasonable, rechecks the computation and watches for <strong style="color:var(--mx-navy)">management bias</strong>. That is direct evidence, so it is sufficient.<br /><br /><strong style="color:var(--mx-navy)">C. Reviewing subsequent events or transactions occurring prior to the date of the auditor's report.</strong> Actual cash collections, settlements or a customer bankruptcy after year end give <strong style="color:var(--mx-navy)">hindsight evidence</strong> about conditions that existed at the balance sheet date. The temptation is to treat anything after year end as outside the audit period, but events before the report date are squarely within the auditor's responsibility.<br /><br /><strong style="color:var(--mx-navy)">D. Developing an independent expectation of the estimate.</strong> Students worry this puts the auditor in management's chair. It does not: the auditor's point estimate or range is built only to <strong style="color:var(--mx-navy)">corroborate</strong> management's number, not to record it. It is an expressly recognized approach and often the strongest evidence available.</p></div>`,},
    {
      id: "316050",
      prompt: `An auditor of a nonissuer needs to obtain audit evidence about a nonissuer's investment in securities that are valued based on the investee's financial results. In order to obtain sufficient appropriate evidence in support of the investee's financial results, the auditor would most appropriately`,
      choices: [
        `Confirm the value of the investment in securities with the investee.`,
        `Obtain and read the investee's financial statements and accompanying auditor's report.`,
        `Examine the nonissuer's computations of the carrying amount of the investments in securities.`,
        `Consult with an actuarial specialist to obtain an expert opinion on the assumptions leading to the nonissuer's computation of the carrying value of the investment in securities.`,
      ],
      correctIndex: 1,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">B. Obtain and read the investee's financial statements and accompanying auditor's report is correct.</strong> The investee's own results are the source data behind the carrying amount, so that is where the evidence has to come from.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">When an investment's carrying amount moves with the investee's earnings, the client is applying the <strong style="color:var(--mx-navy)">equity method</strong>. The balance is a function of the investee's net income or loss, not of a market price, so the evidence must address the <strong style="color:var(--mx-navy)">investee's financial results</strong>. Reading those financial statements, together with the <strong style="color:var(--mx-navy)">auditor's report</strong> on them, gives independent support for the earnings figure the client is using.</p><p style="margin:0 0 18px">If audited statements are unavailable, or the investee's year end differs from the client's, the auditor does more: reads unaudited statements, evaluates the other auditor's work, or requests procedures at the investee. The trap is testing the client's paperwork instead of the <strong style="color:var(--mx-navy)">source data</strong>. Checking arithmetic proves nothing when the income number fed into it is unverified.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. Confirm the value of the investment in securities with the investee.</strong> Confirmation is strong evidence for <strong style="color:var(--mx-navy)">existence and ownership</strong>, such as shares held or ownership percentage, which is why it feels complete. But the investee does not maintain the investor's equity method carrying amount, and a confirmed balance says nothing about the earnings that drive it. This choice answers existence, not <strong style="color:var(--mx-navy)">valuation</strong>.<br /><br /><strong style="color:var(--mx-navy)">C. Examine the nonissuer's computations of the carrying amount.</strong> Recalculation is a real procedure and will sit in the audit program, which is the temptation here. It tests only the <strong style="color:var(--mx-navy)">mathematical accuracy</strong> of a schedule the client prepared from its own inputs. Accurate math applied to an unverified net income figure produces an accurate wrong number.<br /><br /><strong style="color:var(--mx-navy)">D. Consult with an actuarial specialist.</strong> Using a <strong style="color:var(--mx-navy)">specialist</strong> fits valuations built on assumptions outside the auditor's expertise, such as pension obligations or insurance reserves, and that pattern is what students recall. <strong style="color:var(--mx-navy)">Actuaries</strong> model mortality and risk probabilities, not corporate earnings. An equity method balance rests on reported investee results, so no actuarial assumptions are involved.</p></div>`,},
    {
      id: "325050",
      prompt: `An auditor became aware that the legal counsel previously engaged by a nonissuer entity has resigned. What would the auditor most appropriately do in response?`,
      choices: [
        `Inquire of management or others as to why the former legal counsel is no longer associated with the entity.`,
        `Ascertain whether the internal controls of the current legal counsel are as effective as the internal controls of the previous legal counsel.`,
        `Send a letter of inquiry to the entity's current legal counsel requesting a statement of the counsel's understanding of the reasons for the change in legal counsel.`,
        `Send a letter of inquiry to the entity's former legal counsel requesting an explanation of the reasons for the change.`,
      ],
      correctIndex: 0,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">A. Inquire of management or others as to why the former legal counsel is no longer associated with the entity is correct.</strong> The first step is to ask the people who are responsible for the financial statements and who hired the lawyer.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">A lawyer's resignation is a <strong style="color:var(--mx-navy)">risk indicator</strong>, not a routine event. An attorney may be obligated to withdraw when a client ignores advice about a required disclosure, a material loss contingency or an illegal act, so the departure can signal <strong style="color:var(--mx-navy)">unrecorded liabilities or missing disclosures</strong>. The auditor's response is <strong style="color:var(--mx-navy)">inquiry of management or those charged with governance</strong>.</p><p style="margin:0 0 18px">Inquiry comes first because it is immediate and it puts the client's explanation on record, which the auditor then corroborates against board minutes, legal invoices and the <strong style="color:var(--mx-navy)">litigation, claims and assessments letter</strong> sent to current counsel. Do not confuse this with a change in auditors, where direct communication with the <strong style="color:var(--mx-navy)">predecessor auditor</strong> is required. No parallel duty exists for a departed attorney, who remains bound by privilege.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">B. Compare the internal controls of current and previous counsel.</strong> This borrows the logic used for a <strong style="color:var(--mx-navy)">service organization</strong> that processes the client's transactions. A law firm is an outside adviser, not part of the client's information system, and the auditor evaluates <strong style="color:var(--mx-navy)">the client's controls</strong>, not a law firm's internal operations.<br /><br /><strong style="color:var(--mx-navy)">C. Ask current counsel to explain the change.</strong> Students pick this because a letter to current counsel is a real, required procedure, but that letter asks about <strong style="color:var(--mx-navy)">pending litigation, claims and assessments</strong>. A newly engaged firm was not present for the friction that caused the resignation and cannot speak to it.<br /><br /><strong style="color:var(--mx-navy)">D. Ask former counsel to explain the change.</strong> This mirrors the predecessor auditor rule and feels like the most direct source. <strong style="color:var(--mx-navy)">Attorney-client privilege</strong> blocks it: the former lawyer cannot disclose the reasons without the client's consent, so the auditor must start with management.</p></div>`,},
    {
      id: "324050",
      prompt: `Which of the following activities suggests that substantial doubt exists about the ability of an entity to continue as a going concern?`,
      choices: [
        `Refinancing debentures that bear a 10% rate of interest with debentures bearing a 4% rate.`,
        `Outsourcing significant production activities to implement a cost reduction.`,
        `Exhibiting noncompliance with statutory debt requirements.`,
        `Disposing of a plant.`,
      ],
      correctIndex: 2,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">C. Exhibiting noncompliance with statutory debt requirements is correct.</strong> A debt violation is a condition imposed on the entity from outside that can force immediate repayment.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Going concern work has two sides. The auditor first looks for <strong style="color:var(--mx-navy)">conditions and events</strong> that, taken together, raise substantial doubt: defaults on loan terms, recurring operating losses, negative cash flow from operations, loss of a principal customer or supplier, work stoppages. Only if doubt is raised does the auditor move to the second side and evaluate <strong style="color:var(--mx-navy)">management's plans</strong> to see whether those conditions can be relieved.</p><p style="margin:0 0 18px">Noncompliance with statutory debt requirements sits squarely on the first side. A breach can trigger <strong style="color:var(--mx-navy)">acceleration clauses</strong> and other creditor remedies, turning long-term borrowings into an immediate demand for cash the entity may not have. The trap here is that all four choices sound like an entity under pressure, but three of them are <strong style="color:var(--mx-navy)">voluntary actions</strong> taken to conserve or raise cash.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. Refinancing debentures that bear a 10% rate of interest with debentures bearing a 4% rate.</strong> This belongs on the mitigating side of the framework, as a <strong style="color:var(--mx-navy)">plan to restructure debt</strong>. Students are tempted because refinancing can signal trouble, but cutting the rate from 10% to 4% lowers cash outflows and shows lenders were willing to extend credit on better terms.<br /><br /><strong style="color:var(--mx-navy)">B. Outsourcing significant production activities to implement a cost reduction.</strong> This is a <strong style="color:var(--mx-navy)">plan to reduce or delay expenditures</strong>. It tempts because outsourcing usually means shrinking a workforce and looks like retreat, but the stem states the purpose outright: cost reduction, which conserves cash rather than draining it.<br /><br /><strong style="color:var(--mx-navy)">D. Disposing of a plant.</strong> Selling property to raise cash is a classic <strong style="color:var(--mx-navy)">plan to dispose of assets</strong>. Students read "disposing" as liquidating in distress, but nothing here says the plant was essential to operations or sold under creditor pressure, and unloading idle capacity is a normal cash-raising step.</p></div>`,},
    {
      id: "339051",
      prompt: `A recipient of a federal award received two federal grants, as detailed in the following table:
NameGrant Commencement dateGrant AmountYear 1 spendingYear 2 spendingYear 3 spendingYear 4 spendingGrant AJanuary 1, year 1$10,000$1,500$3,800$3,700$400Grant BJanuary 1, year 2$40,000$15,000$9,000$11,000Each grant covers a four-year period. The requirements for each grant indicate that the recipient of the federal award can spend no more than 40% of the individual grant in any year, and no more than 60% of the grant during the first half of the grant term. The recipient of the federal award is in compliance with the grant requirements for`,
      choices: [
        `Grant A, but not Grant B.`,
        `Grant B, but not Grant A.`,
        `Both Grant A and Grant B.`,
        `Neither Grant A nor Grant B.`,
      ],
      correctIndex: 2,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">C. Both Grant A and Grant B is correct.</strong> Neither grant exceeded 40% in any single year or 60% across the first half of its own term.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Compliance testing on a federal award compares actual spending to the limits written into that award, <strong style="color:var(--mx-navy)">one grant at a time</strong>. Two caps apply: no single year above <strong style="color:var(--mx-navy)">40% of the grant amount</strong>, and no more than <strong style="color:var(--mx-navy)">60% through the first half of the grant term</strong>. Convert the percentages to dollars first.</p><p style="margin:0 0 18px">The trap is the timeline. Each grant's first half runs from its <strong style="color:var(--mx-navy)">own commencement date</strong>, not from the first column of the table. Grant A covers Years 1 through 4, so its first half is Years 1 and 2; Grant B covers Years 2 through 5, so its first half is <strong style="color:var(--mx-navy)">Years 2 and 3</strong>. Also, no more than is an <strong style="color:var(--mx-navy)">inclusive ceiling</strong>: a total at exactly the limit is compliant.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The math</h3><div style="background:var(--mx-tint); border-left:4px solid var(--mx-blue); padding:8px 10px; margin-bottom:18px"><table style="border:0; border-collapse:collapse; width:100%"><tbody><tr><td style="border:0; padding:11px 14px; border-bottom:1px solid var(--mx-rule)">Grant A yearly cap, 40% of $10,000</td><td style="border:0; padding:11px 14px; border-bottom:1px solid var(--mx-rule); text-align:right">$4,000</td></tr><tr><td style="border:0; padding:11px 14px; border-bottom:1px solid var(--mx-rule)">Grant A highest single year (Year 2)</td><td style="border:0; padding:11px 14px; border-bottom:1px solid var(--mx-rule); text-align:right">$3,800</td></tr><tr><td style="border:0; padding:11px 14px; border-bottom:1px solid var(--mx-rule)">Grant A first half, Years 1-2 (cap $6,000)</td><td style="border:0; padding:11px 14px; border-bottom:1px solid var(--mx-rule); text-align:right">$5,300</td></tr><tr><td style="border:0; padding:11px 14px; border-bottom:1px solid var(--mx-rule)">Grant B yearly cap, 40% of $40,000</td><td style="border:0; padding:11px 14px; border-bottom:1px solid var(--mx-rule); text-align:right">$16,000</td></tr><tr><td style="border:0; padding:11px 14px; border-bottom:1px solid var(--mx-rule)">Grant B highest single year (Year 2)</td><td style="border:0; padding:11px 14px; border-bottom:1px solid var(--mx-rule); text-align:right">$15,000</td></tr><tr><td style="border:0; padding:11px 14px"><strong style="color:var(--mx-navy)">Grant B first half, Years 2-3 (cap $24,000)</strong></td><td style="border:0; padding:11px 14px; text-align:right"><strong style="color:var(--mx-navy)">$24,000</strong></td></tr></tbody></table></div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. Grant A, but not Grant B.</strong> This comes from reading Grant B's $24,000 through Year 3 as a breach, but no more than 60% means landing exactly on $24,000 is still inside the ceiling. The other route is lining Grant B's first half up with Years 1 and 2 of the table, a year when the grant did not yet exist.<br /><br /><strong style="color:var(--mx-navy)">B. Grant B, but not Grant A.</strong> Students land here by measuring Grant A against the wrong base, often splitting $10,000 into even $2,500 annual slices. Grant A's real limits are $4,000 per year and $6,000 through Year 2; its $3,800 peak and $5,300 first half clear both.<br /><br /><strong style="color:var(--mx-navy)">D. Neither Grant A nor Grant B.</strong> This stacks both errors: treating a total exactly at the limit as an overspend, and using the same calendar years as the first half for both grants. Each grant has its own start date and its own dollar ceilings, and both pass every test.</p></div>`,},
    {
      id: "311051",
      prompt: `For an audit of a nonissuer, an auditor's evaluation of the materiality of a misstatement would be impacted by the extent to which the misstatement does each of the following, except`,
      choices: [
        `Mask a change in earnings trends.`,
        `Affect key ratios.`,
        `Affect compliance with debt covenants.`,
        `Decrease management compensation.`,
      ],
      correctIndex: 3,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">D. Decrease management compensation is correct.</strong> A misstatement that costs management money runs against the incentive to manipulate, so it does not raise the qualitative stakes.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Materiality is not a pure dollar test. A misstatement that is <strong style="color:var(--mx-navy)">quantitatively small</strong> can still be material because of what it does to the reader's conclusions: hiding a trend, flipping a widely watched ratio, curing a covenant breach, or turning a loss into a profit. The auditor weighs these <strong style="color:var(--mx-navy)">qualitative factors</strong> when evaluating uncorrected misstatements.</p><p style="margin:0 0 18px">Every listed factor points the same direction: the misstatement <strong style="color:var(--mx-navy)">benefits the company or its management</strong> at the user's expense. Compensation appears on that list only as a misstatement that <strong style="color:var(--mx-navy)">increases</strong> management's bonus or lets executives hit an incentive target. An error that shrinks the bonus signals no motive to misstate, so it is the exception.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. Mask a change in earnings trends.</strong> This is the classic qualitative factor. A few thousand dollars that converts a first decline in ten quarters into continued growth is trivial in size but changes the story investors are reading. Students skip it because the amount looks immaterial; the <strong style="color:var(--mx-navy)">trend reversal</strong> it conceals is what makes it material.<br /><br /><strong style="color:var(--mx-navy)">B. Affect key ratios.</strong> Analysts, lenders and suppliers evaluate the client on benchmarks such as the current ratio, so an error that pushes a reported ratio across a watched threshold carries weight far beyond its dollar size. The temptation is to treat ratios as <strong style="color:var(--mx-navy)">analytical procedures</strong> rather than a materiality input, but they drive user decisions and are an express factor.<br /><br /><strong style="color:var(--mx-navy)">C. Affect compliance with debt covenants.</strong> A small classification error that keeps a client out of technical default prevents the lender from accelerating the loan, which is a direct economic consequence. Students see it as a legal or disclosure issue instead of a measurement issue. <strong style="color:var(--mx-navy)">Covenant compliance</strong> is one of the strongest qualitative triggers there is.</p></div>`,},
    {
      id: "332050",
      prompt: `Which of the following statements is not correct about obtaining representations by management for audit engagements?`,
      choices: [
        `Management should provide verbal representations that the auditor then documents in working papers.`,
        `Management should disclose whether any events occurred subsequent to the balance sheet date that would require disclosure in the financial statements.`,
        `Management should specifically represent that it believes the financial statements comply with GAAP.`,
        `Management should represent the completeness and availability of all minutes of meetings of stockholders, directors, and committees of directors.`,
      ],
      correctIndex: 0,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">A. Management should provide verbal representations that the auditor then documents in working papers is correct.</strong> Representations must come to the auditor in writing and signed by management, not as the auditor's own notes of a conversation.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Every financial statement audit requires a signed <strong style="color:var(--mx-navy)">management representation letter</strong>. Oral answers given during fieldwork are useful, but they never substitute for the letter, which is typically on client letterhead, signed by those with overall responsibility for the financial statements (usually the CEO and CFO), and <strong style="color:var(--mx-navy)">dated the same date as the auditor's report</strong>.</p><p style="margin:0 0 18px">The letter covers <strong style="color:var(--mx-navy)">all periods presented</strong> and confirms management's responsibility for the statements, the completeness of records and information furnished, and the treatment of subsequent events. Because it is required evidence, a refusal to sign is a <strong style="color:var(--mx-navy)">scope limitation</strong> that normally leads to a disclaimer of opinion or withdrawal.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">B. Subsequent events disclosure.</strong> This is a standard representation, required because the letter is dated as of the report date and must speak to everything through that date. Students doubt it because <strong style="color:var(--mx-navy)">subsequent events</strong> feel like the auditor's own procedure, reviewing later cash receipts and board actions. Those procedures are corroborated by the representation, not replaced by it, so the statement is accurate.<br /><br /><strong style="color:var(--mx-navy)">C. Belief that the statements comply with GAAP.</strong> Management's acknowledgment of responsibility for <strong style="color:var(--mx-navy)">preparation and fair presentation</strong> under the applicable framework is the opening substance of the letter. The temptation is to think GAAP compliance is the auditor's conclusion alone. The auditor opines on it, but management must first assert it.<br /><br /><strong style="color:var(--mx-navy)">D. Completeness and availability of minutes.</strong> Management must confirm that all minutes of stockholder, director and committee meetings have been provided, since withheld minutes can hide <strong style="color:var(--mx-navy)">commitments, litigation or dividend actions</strong>. It sounds like routine record retention that sits outside the letter, which is why students pass over it. Completeness of information is exactly what the letter exists to capture.</p></div>`,},
    {
      id: "329050",
      prompt: `If an auditor of a nonissuer identifies a subsequent event that occurred after the auditor's report date but before the release of the auditor's report, what responsibility, if any, does the auditor have?`,
      choices: [
        `To discuss the matter with management and, when appropriate, those charged with governance.`,
        `To modify the audit opinion and explain the impact of the subsequent event in an additional paragraph in the auditor's report.`,
        `To extend audit testing to include transactions and events up to the date of the subsequent event.`,
        `The auditor has no responsibility for events that occur after the date of the auditor's report.`,
      ],
      correctIndex: 0,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">A. To discuss the matter with management and, when appropriate, those charged with governance is correct.</strong> Inquiry comes first, because what the auditor does next depends on how management responds.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">A fact that becomes known to the auditor <strong style="color:var(--mx-navy)">after the report date but before the report is released</strong> is a subsequently discovered fact. The auditor has <strong style="color:var(--mx-navy)">no duty to keep searching</strong> during this window, but does have a duty to act on anything that lands in front of the audit team and would have mattered at the report date.</p><p style="margin:0 0 18px">The required action is the <strong style="color:var(--mx-navy)">least drastic step</strong>: discuss the matter with management and, where appropriate, those charged with governance. Only after learning whether management will adjust or disclose does the auditor decide on further procedures, <strong style="color:var(--mx-navy)">dual dating</strong>, or a modified opinion. If management fixes the statements properly, an <strong style="color:var(--mx-navy)">unmodified opinion</strong> still stands.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">B. Modify the opinion and add a paragraph.</strong> This is the remedy for a client who <strong style="color:var(--mx-navy)">refuses to correct or disclose</strong> a material matter, not the automatic response to discovering one. Students choose it because the fact sounds material enough to affect the report, but materiality alone does not tell you whether the statements will end up misstated. Until you ask management, there is nothing to modify.<br /><br /><strong style="color:var(--mx-navy)">C. Extend testing through the date of the subsequent event.</strong> Active subsequent event procedures such as reading minutes, cutoff work and legal letters run only <strong style="color:var(--mx-navy)">through the report date</strong>. The temptation is to treat the review period as elastic, but the auditor investigates the specific fact that surfaced rather than reopening the whole engagement for every account.<br /><br /><strong style="color:var(--mx-navy)">D. No responsibility for events after the report date.</strong> This confuses <strong style="color:var(--mx-navy)">no duty to search</strong> with no duty at all. Once a material fact is actually known and the report has not yet been released, the auditor cannot let statements go out that they know may be wrong.</p></div>`,},
    {
      id: "334050",
      prompt: `Which of the following is a significant item that would affect the auditor's report if not resolved?`,
      choices: [
        `A decision made by company management after the balance sheet date to grant employees an additional week of vacation.`,
        `Circumstances that cause the auditor to spend significant hours in excess of allotted engagement hours to complete auditing procedures.`,
        `Significant turnover in a company's clerical staff.`,
        `Circumstances that require the auditor to have significant difficulty in applying auditing procedures the auditor considers necessary.`,
      ],
      correctIndex: 3,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">D. Circumstances that require the auditor to have significant difficulty in applying auditing procedures the auditor considers necessary is correct.</strong> An auditor who cannot carry out a necessary procedure is short of evidence, and that shortage lands in the report.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">The report wording changes for only two reasons: the statements are <strong style="color:var(--mx-navy)">materially misstated</strong>, or the auditor could not obtain <strong style="color:var(--mx-navy)">sufficient appropriate evidence</strong>. Difficulty applying a procedure the auditor considers necessary, whatever the cause, is a <strong style="color:var(--mx-navy)">scope limitation</strong>, and a scope limitation is squarely the second reason.</p><p style="margin:0 0 18px">Work it in order: inquire of management, attempt <strong style="color:var(--mx-navy)">alternative procedures</strong>, then escalate to those charged with governance. Only if it stays <strong style="color:var(--mx-navy)">unresolved</strong> does it reach the opinion: material but confined produces a <strong style="color:var(--mx-navy)">qualified opinion</strong>, material and pervasive produces a <strong style="color:var(--mx-navy)">disclaimer</strong>. Everything else gets handled inside the audit.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. Extra week of vacation granted after the balance sheet date.</strong> This is a <strong style="color:var(--mx-navy)">nonadjusting subsequent event</strong>, a routine business decision affecting future compensation. Students see "after the balance sheet date" and reach for subsequent event reporting consequences, but only conditions that existed at year end change the numbers. No year-end liability exists, so nothing in the report moves.<br /><br /><strong style="color:var(--mx-navy)">B. Hours far in excess of the engagement budget.</strong> A budget overrun is an <strong style="color:var(--mx-navy)">engagement economics and billing matter</strong> between the firm and the client. The word "significant" makes it feel like the scope problem in choice D, but the key fact is that the procedures were completed. The evidence exists, so the opinion is unaffected.<br /><br /><strong style="color:var(--mx-navy)">C. Significant turnover in clerical staff.</strong> Turnover is a <strong style="color:var(--mx-navy)">risk assessment</strong> input that raises control risk. Students equate a weaker control environment with a modified report, but the auditor simply changes the nature, timing and extent of substantive testing. If the expanded testing yields the evidence, the opinion stays unmodified; any significant deficiency is communicated to governance, not written into the opinion.</p></div>`,},
    {
      id: "343051",
      prompt: `Each of the following conditions is required for a practitioner to report on an examination or a review of pro forma financial information, except:`,
      choices: [
        `The practitioner should have an appropriate level of knowledge of the accounting and financial reporting practices of each significant constituent part of the combined entity.`,
        `The historical financial statements of the entity on which the pro forma financial information is based have been audited or reviewed.`,
        `The practitioner's report on pro forma financial information must be added to the practitioner's report on historical financial information.`,
        `The document that contains the pro forma financial information includes complete historical financial statements of the entity for the most recent year.`,
      ],
      correctIndex: 2,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">C. The practitioner's report on pro forma financial information must be added to the practitioner's report on historical financial information is correct.</strong> The pro forma report may stand on its own, so requiring it to be combined is the one statement that is not a condition.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">Pro forma financial information shows what historical results would have looked like if a transaction such as a merger, an acquisition or a disposal had happened earlier. Before examining or reviewing it, the practitioner needs three things: <strong style="color:var(--mx-navy)">historical statements that were audited or reviewed</strong>, <strong style="color:var(--mx-navy)">knowledge of the accounting practices of each significant constituent part</strong> of the combined entity, and a document that <strong style="color:var(--mx-navy)">includes or refers to the complete historical statements</strong> for the most recent year.</p><p style="margin:0 0 18px">The trap is presentation. The pro forma report <strong style="color:var(--mx-navy)">may</strong> be combined with the report on the historical statements, but nothing makes that mandatory. A <strong style="color:var(--mx-navy)">standalone report</strong> is acceptable so long as it identifies the historical statements the information was derived from and states whether those statements were audited or reviewed.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. Appropriate level of knowledge of each significant constituent part.</strong> This is a genuine precondition, not a best practice. Students skip it because it sounds like general due care rather than a stated requirement, but the practitioner cannot judge whether the adjustments are reasonable and correctly computed without understanding how each combining entity accounts for its transactions.<br /><br /><strong style="color:var(--mx-navy)">B. Historical statements audited or reviewed.</strong> This is the hard gate on the engagement. It tempts students who assume the pro forma work itself supplies the assurance, or that compiled source data is close enough. If the underlying historical numbers carry no audit or review, the practitioner must decline the pro forma engagement.<br /><br /><strong style="color:var(--mx-navy)">D. Document includes complete historical statements for the most recent year.</strong> Users need a baseline to compare the hypothetical figures against, so the document must contain those statements or point to ones that are readily available. Students discard this because the requirement can be satisfied by a reference, which makes it feel optional. It is still a stated condition, so it is not the exception.</p></div>`,},
    {
      id: "340052",
      prompt: `In which of the following paragraphs in an accountant's review report should an accountant include a description of an issue that was appropriately disclosed in the financial statements and that the accountant concludes would be fundamental to the users' understanding?`,
      choices: [
        `The conclusion paragraph.`,
        `An other-matter paragraph.`,
        `The introductory paragraph.`,
        `An emphasis-of-matter paragraph.`,
      ],
      correctIndex: 3,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">D. An emphasis-of-matter paragraph is correct.</strong> The matter is already disclosed in the statements, so the accountant simply points the reader to it.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">A review report can carry two kinds of add-on paragraphs, and the test is <strong style="color:var(--mx-navy)">where the information lives</strong>. An <strong style="color:var(--mx-navy)">emphasis-of-matter paragraph</strong> draws attention to something <strong style="color:var(--mx-navy)">appropriately presented or disclosed in the financial statements</strong> that is fundamental to users' understanding. Going concern uncertainty, a major subsequent event, and a change in accounting principle are the classic triggers.</p><p style="margin:0 0 18px">The paragraph <strong style="color:var(--mx-navy)">highlights, it never modifies</strong>. It follows the conclusion, refers the reader to the specific note, and closes by stating that the accountant's conclusion is <strong style="color:var(--mx-navy)">not modified</strong> with respect to the matter. If the disclosure were missing or wrong, the accountant would be reporting a known departure instead, which is a different problem entirely.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. The conclusion paragraph.</strong> That paragraph exists to express <strong style="color:var(--mx-navy)">limited assurance</strong>: whether the accountant is aware of material modifications needed. Students reach for it because the matter is significant, but writing narrative there would suggest the conclusion itself is affected. Here it is not.<br /><br /><strong style="color:var(--mx-navy)">B. An other-matter paragraph.</strong> Right family, wrong half. Other-matter paragraphs cover items <strong style="color:var(--mx-navy)">not presented or disclosed in the statements</strong> but relevant to understanding the engagement, the accountant's responsibilities, or the report, such as prior period statements handled by a predecessor. This issue sits inside the statements, so emphasis of matter applies.<br /><br /><strong style="color:var(--mx-navy)">C. The introductory paragraph.</strong> This is scoping language: it names the entity, lists the statements and periods reviewed, and explains that a review is substantially less in scope than an audit. It is tempting because it is the first thing a reader sees, but it never carries commentary on individual disclosures.</p></div>`,},
    {
      id: "344050",
      prompt: `A report on a nonissuer's compliance with a contractual agreement includes a statement that nothing came to the auditor's attention that caused the auditor to believe that the nonissuer failed to comply with the terms of the contractual agreement. This statement in the report on compliance would not be appropriate if the auditor`,
      choices: [
        `Issues a separate report on compliance.`,
        `Disclaims an opinion on the financial statements.`,
        `Expresses a qualified opinion on the financial statements.`,
        `Includes the report on compliance with the auditor's report on the financial statements.`,
      ],
      correctIndex: 1,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">B. Disclaims an opinion on the financial statements is correct.</strong> Negative assurance on compliance has to rest on an audited set of financial statements, and a disclaimer means there is no audit conclusion to rest on.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">A report on compliance with a contractual agreement issued in connection with a financial statement audit carries <strong style="color:var(--mx-navy)">negative assurance</strong>: nothing came to the auditor's attention suggesting noncompliance. That wording is available only when the auditor has <strong style="color:var(--mx-navy)">audited the statements</strong> and expressed an <strong style="color:var(--mx-navy)">unmodified or qualified opinion</strong>. The compliance work rides on the audit, so it borrows the audit's credibility.</p><p style="margin:0 0 18px">The trap is severity. A qualified opinion still leaves an audit that functioned, so negative assurance survives, with language noting the modification. An <strong style="color:var(--mx-navy)">adverse opinion or a disclaimer</strong> removes that foundation entirely, and negative assurance on compliance is then <strong style="color:var(--mx-navy)">prohibited</strong>. Format is never the issue: the compliance report may stand alone or sit inside the audit report.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. Issues a separate report on compliance.</strong> This confuses <strong style="color:var(--mx-navy)">delivery format</strong> with level of assurance. Students pick it because a standalone compliance report feels detached from the audit, as though it could not lean on audit work, but the separate report still states that it was prepared in connection with the audit of the financial statements. Negative assurance is appropriate either way.<br /><br /><strong style="color:var(--mx-navy)">C. Expresses a qualified opinion on the financial statements.</strong> This is the closest call, because any modified opinion feels like it should disqualify the wording. A qualified opinion is an <strong style="color:var(--mx-navy)">except-for</strong> conclusion: the auditor obtained sufficient evidence and the statements are fairly presented apart from one identified matter, so the audit foundation exists. Negative assurance on compliance is still permitted, with the report disclosing the qualification.<br /><br /><strong style="color:var(--mx-navy)">D. Includes the report on compliance with the auditor's report on the financial statements.</strong> Combining the two is a standard presentation, handled as an <strong style="color:var(--mx-navy)">other-matter paragraph</strong>. The temptation is to think that mixing compliance language into the audit report contaminates the opinion, but that paragraph is clearly separated from the opinion section. Presentation choice does not change what assurance the auditor may give.</p></div>`,},
    {
      id: "37050",
      prompt: `Each of the following criteria must be present for a change in accounting methodology of an issuer to be characterized as a change in accounting principle, except:`,
      choices: [
        `The method of accounting for the effect of the change is in conformity with generally accepted accounting principles.`,
        `The disclosures related to the change are adequate.`,
        `The previous accounting methodology was not based on a generally accepted accounting principle.`,
        `The newly adopted accounting methodology is based on a generally accepted accounting principle.`,
      ],
      correctIndex: 2,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">C. The previous accounting methodology was not based on a generally accepted accounting principle is correct.</strong> A change in principle moves from one acceptable principle to another, so the old method has to have been acceptable to begin with.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">A <strong style="color:var(--mx-navy)">change in accounting principle</strong> is a switch from one generally accepted principle to another generally accepted principle. Before the auditor treats a change that way, three things must be true: the <strong style="color:var(--mx-navy)">newly adopted method is acceptable</strong>, the <strong style="color:var(--mx-navy)">effect of the change is accounted for properly</strong>, and management has <strong style="color:var(--mx-navy)">adequate disclosure</strong> supported by a preferability justification.</p><p style="margin:0 0 18px">The trap is the starting point. If the company had been using a method that was never acceptable, moving to an acceptable one is a <strong style="color:var(--mx-navy)">correction of an error</strong>, not a change in principle. That distinction drives the reporting: an error correction means <strong style="color:var(--mx-navy)">restating</strong> the prior statements and disclosing the misstatement, while a valid change in principle is applied retrospectively and flagged as a <strong style="color:var(--mx-navy)">consistency</strong> matter in the auditor's report.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. The method of accounting for the effect of the change is in conformity with GAAP.</strong> This is one of the required criteria, so it cannot be the exception. The auditor verifies that the cumulative effect and any retrospective adjustment to beginning retained earnings were computed and recorded correctly. Students skip past it because it sounds procedural, but a change recorded incorrectly is a GAAP departure, not a clean change in principle.<br /><br /><strong style="color:var(--mx-navy)">B. The disclosures related to the change are adequate.</strong> Also required. The notes must give the nature of the change, why the new method is preferable, and the dollar effect on income and earnings per share for the periods presented. Weak disclosure does not reclassify the change into something else, it makes the statements deficient, which is exactly why this criterion sits on the list.<br /><br /><strong style="color:var(--mx-navy)">D. The newly adopted accounting methodology is based on a GAAP principle.</strong> This is the mirror image of the correct answer, and that similarity is what makes it tempting. Students remember that GAAP appears on one side of the test and grab the wrong side. Both ends must be acceptable: a company cannot move to a non-GAAP method and call it a change in principle, so this criterion is required rather than excepted.</p></div>`,},
    {
      id: "339052",
      prompt: `When an auditor issues an opinion on the financial statements and a report on internal control over financial reporting of a governmental entity, the auditor's report should also include`,
      choices: [
        `All indicators of fraud risk.`,
        `Economic conditions that affect the entity's viability.`,
        `A description of the scope of the auditor's testing of internal control over financial reporting.`,
        `A description of noncompliance with contracts that has an immaterial effect on financial data significant to the audit.`,
      ],
      correctIndex: 2,
      explanation: `<div style="--mx-navy:#01506e; --mx-blue:#207bb5; --mx-lightblue:#0099d4; --mx-yellow:#e9dc12; --mx-grey:#4B556A; --mx-rule:#dde4ea; --mx-tint:#f2f7fa; --mx-body:#232a33; color:var(--mx-body); line-height:1.6"><div style="background:var(--mx-tint); border-left:4px solid var(--mx-yellow); padding:13px 18px; margin-bottom:18px"><strong style="color:var(--mx-navy)">C. A description of the scope of the auditor's testing of internal control over financial reporting is correct.</strong> A government audit report must tell the reader how far the internal control and compliance testing actually went.</div><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">The rule</h3><p style="margin:0 0 12px">A governmental entity audit follows generally accepted auditing standards plus the added <strong style="color:var(--mx-navy)">Government Auditing Standards</strong>, the Yellow Book. Beyond the opinion on the financial statements, the auditor issues a separate report describing the <strong style="color:var(--mx-navy)">scope and results</strong> of testing of internal control over financial reporting and of <strong style="color:var(--mx-navy)">compliance</strong> with laws, regulations, contracts and grant agreements.</p><p style="margin:0 0 18px">The trap is thinking that report is an <strong style="color:var(--mx-navy)">opinion on internal control</strong>. It is not. It states what was tested, what was found, and that the testing was not performed to express an opinion on effectiveness. Its content is limited to scope, results, and matters that are <strong style="color:var(--mx-navy)">material or otherwise significant</strong>.</p><h3 style="color:var(--mx-navy); font-size:17px; margin:0 0 8px">Why the others are wrong</h3><p style="margin:0; color:var(--mx-grey)"><strong style="color:var(--mx-navy)">A. All indicators of fraud risk.</strong> Fraud risk factors belong to <strong style="color:var(--mx-navy)">planning and risk assessment</strong>, where they are brainstormed and documented, and to communications with those charged with governance. Students pick this because governmental reporting does expand fraud responsibilities. But only fraud that is material or significant to the audit gets reported; a catalog of every risk indicator never reaches the report.<br /><br /><strong style="color:var(--mx-navy)">B. Economic conditions that affect the entity's viability.</strong> Economic context sits in <strong style="color:var(--mx-navy)">management's discussion and analysis</strong> or in a going concern disclosure when substantial doubt exists. It is tempting because governmental reports are written for public readers who care about fiscal health. The auditor's report, though, addresses testing performed, not a forecast of the entity's future.<br /><br /><strong style="color:var(--mx-navy)">D. A description of noncompliance with contracts that has an immaterial effect on financial data significant to the audit.</strong> This confuses the <strong style="color:var(--mx-navy)">reporting threshold</strong>. Material or otherwise significant noncompliance goes in the report; immaterial instances are communicated to management, often in a management letter. The phrase "significant to the audit" is the bait, but the effect described is immaterial.</p></div>`,},
  ],
};
